insert into public.questions (id, tema, ano, instituicao, enunciado, comentario, comentario_completo) values

('91903d7c-edc9-4378-914e-fb03c2e2e2f3', 'Miocárdio', 2016, 'TEC', 'Quais são os fatores de risco para morte súbita na cardiopatia hipertrófica? Marcar a alternativa com mais fatores positivos:', 'Os principais marcadores de risco para morte súbita na CMH são: TVNS documentada, síncope inexplicada e resposta pressórica anormal (hipotensão) ao esforço — reunidos na alternativa E.', 'Os fatores de risco maiores clássicos para morte súbita na cardiomiopatia hipertrófica (CMH) incluem: taquicardia ventricular não sustentada (TVNS) no Holter, síncope inexplicada, história familiar de morte súbita, espessura parietal máxima ≥ 30 mm, resposta pressórica anormal (hipotensão) ao exercício, e — mais recentemente — extensão de fibrose ao realce tardio na ressonância e presença de aneurisma apical. A alternativa E reúne três desses marcadores maiores (taquicardia ventricular, síncope e hipotensão ao exercício), sendo a que concentra mais fatores de risco positivos reconhecidos.

Por que as outras alternativas têm menos fatores de risco genuínos:
• A) Aneurisma ventricular é, de fato, um marcador (mais recentemente reconhecido), mas "TVNS prolongada" e "espessura entre 11-15 mm" não são os critérios clássicos (a espessura de risco é ≥ 30 mm, não 11-15 mm, que é discreta).
• B) Espessura septal > 30 mm e FA são fatores relevantes, mas "história familiar" aqui não especifica que seja de morte súbita (o fator de risco é história familiar de morte súbita, não de CMH em geral).
• C) Hipotensão ao exercício é fator real, mas "oligossintomático" não é fator de risco — pelo contrário, costuma ser um marcador de menor risco.
• D) Síncope e história familiar são fatores reais, mas "aumento do volume do átrio esquerdo" isoladamente não é um dos marcadores maiores clássicos.'),

('2864e426-efd9-4f25-8baf-96c0f40d24ca', 'Miocárdio', 2022, 'TEC', 'Paciente de 72 anos de idade, com quadro de dispneia aos pequenos esforços, edema de membros inferiores, ortopneia e dispneia paroxística noturna há 9 meses. O eletrocardiograma releva bloqueio atrioventricular de 1º grau, baixa voltagem em derivações periféricas. O ecocardiograma apresentou hipertrofia biventricular e espessamento das valvas aórtica e mitral, espessamento do septo interatrial e padrão de strain global longitudinal, conforme Figura 1, fração de ejeção de ventrículo esquerdo de 56%, dilatação biatrial importante. Laboratório: gamopatia monoclonal presente na imunofixação de proteínas séricas. A cintilografia óssea com pirofosfato com tecnécio apresenta-se na Figura 2.
Em relação a esse caso, assinale a alternativa correta:', 'A presença de gamopatia monoclonal torna a amiloidose por cadeias leves (AL) o diagnóstico mais provável — e como a cintilografia com pirofosfato pode dar falso-positivo justamente na amiloidose AL, ela não é confiável nesse contexto específico e não substitui a investigação hematológica.', 'Este caso reúne achados clássicos de amiloidose cardíaca: baixa voltagem no ECG associada a hipertrofia biventricular ("desproporção eletrocardiográfica-ecocardiográfica"), espessamento valvar e do septo interatrial, padrão de strain longitudinal com "apical sparing", e dilatação biatrial. A presença de gamopatia monoclonal na imunofixação sérica levanta forte suspeita de amiloidose por cadeias leves (AL), não por transtirretina (ATTR). Nesse cenário, a cintilografia óssea com pirofosfato de tecnécio — apesar de ter alta sensibilidade/especificidade para ATTR quando não há gamopatia — pode ser positiva por depósito inespecífico também na amiloidose AL (falso-positivo para o diagnóstico de ATTR), então ela não pode substituir a investigação hematológica (eletroforese, imunofixação, biópsia de gordura abdominal) para confirmar/excluir AL antes de se firmar o diagnóstico.

Por que as outras alternativas estão incorretas:
• A) O ECG e o ecocardiograma já SÃO indicativos de amiloidose cardíaca (baixa voltagem + hipertrofia + apical sparing); a ressonância é útil, mas não é "imperativa" da forma descrita, e a frase erra ao dizer que ECG/eco não são indicativos.
• B) O apical sparing É, sim, um achado clássico e sugestivo de amiloidose cardíaca (não o contrário do que a alternativa afirma).
• D) A cintilografia com pirofosfato NÃO tem 100% de especificidade quando há gamopatia monoclonal concomitante — por isso outros exames (eletroforese/imunofixação) são obrigatórios para excluir AL antes de assumir ATTR.
• E) A baixa voltagem tem sensibilidade baixa (não alta) para amiloidose cardíaca — está presente em apenas uma minoria dos pacientes, sendo mais sensível em ATTR do que em AL.'),

('2297d06e-10a7-4b44-8fdd-5dda2e5b3027', 'Miocárdio', 2019, 'TEC', 'Em relação à amiloidose cardíaca, assinale a alternativa INCORRETA:', 'A amiloidose AL (cadeias leves) decorre da proliferação de plasmócitos/células B produzindo cadeias leves de imunoglobulina — não é um "depósito reativo" ligado a doenças crônicas/inflamatórias (isso descreve a amiloidose AA), e também não tem "boa resposta" a um tratamento simples — por isso essa é a alternativa incorreta.', 'A amiloidose AL (de cadeias leves) resulta de uma discrasia de plasmócitos (ou linfócitos B) que produzem cadeias leves de imunoglobulina em excesso, as quais se depositam nos tecidos, incluindo o coração. A descrição da alternativa D — "depósito reativo de imunoglobulinas, denominado amiloide A (AL), associada a doenças crônicas, infecciosas e inflamatórias, com boa resposta ao tratamento específico" — mistura a fisiopatologia da amiloidose AA (secundária/reativa, ligada a doenças inflamatórias crônicas, que de fato tem boa resposta ao tratamento da doença de base) com a nomenclatura da amiloidose AL, e por isso está INCORRETA como descrição do que é a AL.

Por que as outras alternativas estão corretas (não são a resposta, já que a pergunta pede a incorreta):
• A) A forma familiar (hereditária) de amiloidose por transtirretina (ATTRv) associa-se, de fato, a mutações no gene da transtirretina, e o transplante hepático (fonte da TTR mutante) é, de fato, uma opção terapêutica quando feito precocemente.
• B) Cerca de 25% (um quarto) dos pacientes com amiloidose ATTR (selvagem ou hereditária) desenvolvem envolvimento cardíaco relevante, com distúrbios de condução ou insuficiência cardíaca.
• C) Hipotensão postural, nefropatia e neuropatia periférica (incluindo síndrome do túnel do carpo bilateral, um sinal de alerta) são, de fato, manifestações extracardíacas frequentes da amiloidose.
• E) Turgência jugular, edemas e hepatomegalia (sinais de insuficiência cardíaca direita/restritiva) e hipofonese de B1 (pelo espessamento infiltrativo do miocárdio atrial e valvar) são, de fato, achados típicos ao exame físico.'),

('e15135e0-0180-4d49-85b5-64a450196995', 'Miocárdio', 2019, 'TEC', 'Com referência aos fatores de risco para morte súbita, é INCORRETO afirmar que:', 'A cardiomiopatia hipertrófica não obstrutiva TAMBÉM é marcador de risco para morte súbita (o risco de CMH independe de haver obstrução dinâmica da via de saída) — por isso essa é a alternativa incorreta.', 'A presença de cardiomiopatia hipertrófica — obstrutiva ou não obstrutiva — já constitui, por si só, um marcador de risco para morte súbita cardíaca; a estratificação de risco na CMH não se baseia na presença ou ausência de obstrução dinâmica da via de saída do VE, mas em outros marcadores (síncope, TVNS, história familiar, espessura parietal, resposta pressórica ao esforço, fibrose ao realce tardio). Por isso, afirmar que a forma "não obstrutiva não se constitui marcador de risco" está INCORRETO.

Por que as outras alternativas estão corretas (não são a resposta, já que a pergunta pede a incorreta):
• B) A incidência de morte súbita em lactentes (< 1 ano) é, de fato, comparável à observada em adultos de meia-idade ou mais velhos — as curvas de incidência de morte súbita cardíaca têm formato bimodal/em "U".
• C) A síndrome do QT longo congênito é, de fato, uma canalopatia genética que aumenta o risco de morte súbita por arritmias ventriculares (Torsades de Pointes).
• D) A doença arterial coronariana é, de fato, a principal base estrutural/etiológica da morte súbita cardíaca na população geral (especialmente em adultos mais velhos).
• E) A morte súbita cardíaca pode, de fato, ser a primeira manifestação clínica da doença coronariana em uma proporção significativa (até cerca de metade) dos casos.'),

('5a80acf2-75a9-4c16-8eac-b54f3dfa43c9', 'Miocárdio', 2019, 'TEC', 'Assinale a alternativa correta acerca dos achados na miocardiopatia hipertrófica com obstrução dinâmica na via de saída do ventrículo esquerdo:', 'O tratamento invasivo (miectomia cirúrgica ou alcoolização septal) é indicado para pacientes sintomáticos refratários ao tratamento farmacológico otimizado (betabloqueador, bloqueador de canal de cálcio, disopiramida).', 'Na cardiomiopatia hipertrófica obstrutiva (CMHO), quando os sintomas (geralmente dispneia e/ou angina) persistem apesar do tratamento farmacológico otimizado (betabloqueadores, verapamil/diltiazem e, quando disponível, disopiramida), está indicada terapia de redução septal invasiva — miectomia cirúrgica (padrão-ouro) ou alcoolização septal percutânea, dependendo do perfil do paciente e da experiência do centro.

Por que as outras alternativas estão incorretas:
• A) O sopro da CMHO é SISTÓLICO (não diastólico) de ejeção; e ele se torna MAIS intenso (não menos) com manobras que reduzem a pré-carga/pós-carga, como a Valsalva, pois isso aumenta o gradiente dinâmico.
• B) É o contrário: a ressonância magnética cardíaca SUPERA o ecocardiograma para caracterizar hipertrofia apical/anterolateral e quantificar fibrose (via realce tardio), sendo o ecocardiograma limitado nessas regiões.
• D) Pacientes com CMHO PODEM evoluir, numa minoria dos casos, para a chamada "fase dilatada/burned-out", com disfunção sistólica, remodelamento, afilamento parietal e dilatação de câmaras — o oposto do afirmado.
• E) A alcoolização septal reduz de forma significativa (não discreta) o gradiente e melhora os sintomas na maioria dos pacientes bem selecionados, sendo uma alternativa à cirurgia, não um passo intermediário que costuma precisar de cirurgia posterior na maioria dos casos.'),

('65449044-2577-40db-a95d-ddc89424fc91', 'Miocárdio', 2019, 'TEC', 'Homem, 50 anos, com história de falta de ar aos esforços há dois anos, associada à ortopneia e dispneia paroxística noturna. Apresentava queixa de palpitações eventuais. O eletrocardiograma revelou frequência cardíaca (FC) = 67 bpm, bloqueio de ramo direito e bloqueio divisional anterossuperior esquerdo. O Holter revelou episódios de taquicardia ventricular não sustentada em alta densidade e um episódio de taquicardia ventricular sustentada, assintomática. O ecocardiograma demonstrou disfunção sistólica moderada do ventrículo esquerdo. O exame sorológico confirmou sorologia de Chagas positiva. Assinale a alternativa correta em relação ao caso clínico:', 'Na cardiomiopatia chagásica com disfunção ventricular e arritmia ventricular complexa, a amiodarona é o antiarrítmico mais utilizado, mas estudos observacionais associam seu uso à maior mortalidade nesse contexto — por isso deve ser usada com cautela e ponderação de risco-benefício.', 'Na cardiomiopatia chagásica crônica com disfunção ventricular e arritmia ventricular complexa (como neste caso, com TV sustentada e TVNS de alta densidade), a amiodarona é o antiarrítmico mais empregado para o controle de arritmias, mas dados observacionais (incluindo do estudo GESICA/subanálises chagásicas) associam seu uso a maior mortalidade nessa população — reforçando que a decisão terapêutica deve pesar o risco-benefício e, muitas vezes, favorecer a indicação de CDI em vez de depender apenas do antiarrítmico.

Por que as outras alternativas estão incorretas:
• A) Antiarrítmicos da classe I (como a quinidina) são, na verdade, CONTRAINDICADOS (e não reservados/indicados) em pacientes chagásicos com disfunção ventricular, pelo risco de efeito pró-arrítmico e depressão miocárdica.
• B) TVNS de alta densidade no Holter, num paciente com disfunção ventricular por Chagas, TEM implicação prognóstica adversa (é marcador de risco), não sendo um achado sem relevância.
• D) Um único episódio de TV sustentada assintomática não indica ablação como conduta imediata de primeira linha; a prioridade é avaliação de risco de morte súbita e possível indicação de CDI.
• E) Bloqueio bifascicular isolado não é, por si só, indicação de marca-passo definitivo; marca-passo é reservado para bloqueio AV avançado/sintomático documentado, não como profilaxia baseada apenas no bloqueio de ramo.'),

('1ea3ec65-e366-48e7-bb17-bb3bcc983905', 'Miocárdio', 2022, 'TEC', 'Em relação à suspeita de amiloidose cardíaca, assinale a sequência mais adequada para o diagnóstico:', 'O fluxograma diagnóstico começa pela pesquisa de cadeia leve monoclonal (para excluir AL), seguida da cintilografia com traçador ósseo (para confirmar ATTR) e, por fim, do sequenciamento genético da transtirretina (para diferenciar a forma hereditária da senil/selvagem).', 'O fluxograma diagnóstico recomendado para suspeita de amiloidose cardíaca começa pela pesquisa de discrasia de células plasmáticas (eletroforese de proteínas + imunofixação sérica/urinária + cadeias leves livres no sangue), para excluir ou confirmar amiloidose AL — etapa crítica, pois muda completamente o tratamento. Se essa pesquisa for negativa, segue-se para a cintilografia com traçador ósseo (pirofosfato de tecnécio), que tem alta sensibilidade e especificidade para amiloidose por transtirretina (ATTR) quando não há gamopatia monoclonal concomitante. Por fim, uma vez confirmada a ATTR, faz-se o sequenciamento genético do gene da transtirretina para diferenciar a forma hereditária (variante) da forma senil/selvagem (wild-type), o que tem implicações prognósticas e para rastreamento familiar.

Por que as outras alternativas estão incorretas:
• A, C e E) Colocam a cintilografia ou o sequenciamento genético ANTES da pesquisa de cadeia leve monoclonal — isso é um erro de sequência grave, pois um resultado positivo na cintilografia sem excluir antes a gamopatia monoclonal pode levar a um diagnóstico falso de ATTR quando, na verdade, se trata de AL (cintilografia pode ser falso-positiva na AL).
• D) Coloca o sequenciamento genético antes da cintilografia — inverte a ordem lógica, já que o sequenciamento só é útil depois de confirmada a ATTR pela cintilografia (não há motivo para sequenciar o gene antes de saber se o paciente tem ATTR).'),

('dfe28064-419e-4a37-8e3c-2f260fcaf9ad', 'Miocárdio', 2020, 'TEC', 'Mulher, 38 anos, com diagnóstico de cardiomiopatia hipertrófica, apresenta-se com dispneia aos esforços em caráter progressivo que havia iniciado nos últimos seis meses. Ecocardiograma evidenciou hipertrofia septal com espessura de 28 mm, fração de ejeção normal e disfunção diastólica com padrão de relaxamento alterado. A velocidade do fluxo sanguíneo na via de saída do ventrículo esquerdo = 1,8 m/s e a pressão sistólica estimada na artéria pulmonar = 42 mmHg. Assinale a alternativa correta em relação à propedêutica para avaliação dos sintomas:', 'A ressonância cardíaca permite quantificar a fibrose miocárdica (via realce tardio), informação relevante para a estratificação de risco de morte súbita na cardiomiopatia hipertrófica.', 'A ressonância magnética cardíaca é uma ferramenta complementar valiosa na avaliação da cardiomiopatia hipertrófica, pois permite quantificar com precisão a extensão da fibrose miocárdica através da técnica de realce tardio pelo gadolínio — informação com relevância prognóstica e que vem sendo incorporada aos escores de estratificação de risco de morte súbita, além de ajudar no diagnóstico diferencial com outras causas de hipertrofia (amiloidose, doença de Fabry).

Por que as outras alternativas estão incorretas:
• A) A velocidade de fluxo na via de saída de 1,8 m/s corresponde a um gradiente de apenas ~13 mmHg (Bernoulli simplificado), ou seja, sem obstrução significativa em repouso — não há indicação clara de ecoestresse com dobutamina (que, além disso, é evitado na CMH pelo risco de induzir gradiente dinâmico perigoso e arritmias).
• B) O movimento anterior sistólico (SAM) da valva mitral é, na verdade, uma causa FREQUENTE (não rara) de obstrução dinâmica na via de saída do VE na CMH.
• C) É o inverso: maior espessura parietal está mais associada a risco de morte súbita do que a sintomas de insuficiência cardíaca propriamente ditos, que se correlacionam mais com disfunção diastólica e obstrução.
• D) A disfunção diastólica está associada à gravidade da hipertrofia, mas a causa mais provável de dispneia nesta paciente (com gradiente de VSVE não obstrutivo em repouso) inclui também a possibilidade de obstrução latente/exercício e outros mecanismos, não sendo simplesmente "a causa provável" isolada e definitiva sem investigação adicional.'),

('b5fffa7c-e31f-4081-b81a-8aacde39f791', 'Miocárdio', 2019, 'TEC', 'Homem, 27 anos, apresenta-se com queixas de palpitações. Nega uso de drogas ou tabagismo. Pratica exercícios físicos regularmente. História familiar de cardiomiopatia hipertrófica. Exame físico completamente normal, incluindo ausculta cardíaca em repouso e durante Manobra de Valsalva. Eletrocardiograma (ECG) evidenciou hipertrofia ventricular esquerda com alterações da repolarização ventricular. Ecocardiograma mostrou hipertrofia septal com espessura diastólica de 26 mm. Leve movimento anterior sistólico da valva mitral. Ausência de gradiente intracavitário tanto em repouso como durante Manobra de Valsalva. Fração de ejeção (FE) de 75%, sem alteração segmentar da contratilidade. Assinale a alternativa correta:', 'Na CMH não obstrutiva, os principais determinantes da progressão para insuficiência cardíaca são a obstrução da via de saída (quando presente), a fibrilação atrial e a disfunção diastólica — não a obstrução isoladamente.', 'Na cardiomiopatia hipertrófica (obstrutiva ou não), os três principais determinantes fisiopatológicos da progressão para insuficiência cardíaca são: a obstrução dinâmica da via de saída do VE (quando presente), o desenvolvimento de fibrilação atrial (que compromete o enchimento ventricular ao perder a contração atrial em um ventrículo já com relaxamento prejudicado) e a disfunção diastólica intrínseca do miocárdio hipertrófico. Este paciente, embora não obstrutivo neste momento, está sob risco desses mesmos mecanismos ao longo do tempo.

Por que as outras alternativas estão incorretas:
• A) Alternância de onda T é um marcador de risco descrito para outras condições (como canalopatias/síndrome do QT longo), não um dos marcadores maiores clássicos de risco de morte súbita na CMH.
• B) A amiodarona não é considerada terapêutica de escolha "para prevenção de morte súbita" na CMH — a prevenção de morte súbita nos pacientes de alto risco se dá com CDI, não com antiarrítmico isolado.
• C) É o inverso do afirmado para a fisiopatologia da IC progressiva: maior espessura parietal correlaciona-se mais com risco de morte súbita do que com sintomas de IC propriamente.
• E) A isquemia microvascular é, de fato, um componente fisiopatológico importante na CMH, mas ELA TEM sim impacto no prognóstico (relaciona-se a fibrose, arritmias e evolução para a fase dilatada), contrariamente ao que a alternativa afirma.'),

('5eb43b26-32ce-4f4e-9ef0-5810d714630d', 'Miocárdio', 2020, 'TEC', 'Homem, 73 anos, diagnóstico de hipertensão há 10 anos bem controlada, em uso de ramipril 5 mg/dia. Procura atendimento para risco cirúrgico para cirurgia ortopédica de correção de ruptura do tendão do bíceps do braço direito. Relata dispneia aos esforços habituais, progressiva, há três meses. Exame clínico: "Sinal do Popeye" no braço direito. Pressão arterial = 118 x 72 mmHg sentado e 92 x 60 mmHg em pé. Frequência cardíaca = 60 bpm. B4. Ausência de sopros. Eletrocardiograma: bloqueio atrioventricular de 1º grau, bloqueio completo do ramo esquerdo. Ecocardiograma: aumento biatrial, septo interventricular (SIV) = 13 mm, strain sistólico longitudinal compatível com apical sparing. Assinale a alternativa correta:', 'O quadro (idoso, ruptura espontânea de tendão bicipital, hipotensão ortostática, B4, hipertrofia leve/moderada com apical sparing no strain) é sugestivo de amiloidose cardíaca — a melhor estratégia diagnóstica combina eletroforese/imunofixação de proteínas com cintilografia com pirofosfato.', 'Este caso reúne pistas clássicas (mas sutis) de amiloidose cardíaca no idoso: ruptura espontânea do tendão bicipital ("sinal do Popeye" — depósito amiloide em tendões), hipotensão ortostática, B4 (embora a presença de B4 seja controversa numa cardiopatia restritiva com átrios não complacentes, é descrita), bloqueio de ramo esquerdo com BAV de 1º grau (desproporção entre o pouco espessamento do septo e o comprometimento elétrico) e strain com padrão de apical sparing. A melhor estratégia diagnóstica inicial é, portanto, rastrear amiloidose combinando a pesquisa de discrasia de plasmócitos (eletroforese de proteínas, imunofixação sérica e urinária) com a cintilografia óssea com pirofosfato de tecnécio, que juntas permitem diferenciar AL de ATTR.

Por que as outras alternativas estão incorretas:
• A) A hipótese mais provável não é doença arterial coronariana — não há dor torácica, isquemia ou fatores de risco coronarianos proeminentes que justifiquem essa ser a hipótese principal frente ao conjunto de achados sugestivos de doença infiltrativa.
• B) A endomiocardiofibrose é uma miocardiopatia restritiva tropical, mas não se encaixa no perfil (idoso não característico da região endêmica típica, sinal do Popeye e strain com apical sparing não são achados de EMF).
• C) A hemocromatose causa miocardiopatia dilatada/mista, não o padrão restritivo com apical sparing e sinal do Popeye descritos; a queixa de ruptura tendínea não é achado de sobrecarga de ferro.
• E) A biópsia endomiocárdica com vermelho Congo é o padrão-ouro histológico, mas não é o passo INICIAL "imperativo" quando exames não invasivos (eletroforese + cintilografia) já podem estabelecer o diagnóstico na maioria dos casos, reservando-se a biópsia para casos duvidosos.'),

('87ce8376-e72b-4d81-9379-2817ac5221d5', 'Miocárdio', 2022, 'TEC', 'Assinale a alternativa correta quanto à indicação da avaliação genética na cardiomiopatia hipertrófica:', 'O principal papel estabelecido do teste genético na CMH é o rastreamento em cascata de familiares de primeiro grau de um paciente com diagnóstico confirmado (e mutação identificada).', 'A principal utilidade clínica estabelecida da avaliação genética na cardiomiopatia hipertrófica é permitir o rastreamento em cascata de familiares de primeiro grau: uma vez identificada a mutação causadora no paciente-índice, testa-se especificamente essa mutação nos parentes, permitindo identificar precocemente portadores (mesmo antes do fenótipo se manifestar) e direcionar o acompanhamento clínico.

Por que as outras alternativas estão incorretas:
• A) O teste genético não é usado para estratificar risco de morte súbita/indicação de CDI — essa decisão se baseia em marcadores clínicos, de imagem e Holter, não no genótipo isoladamente.
• B) O teste genético é, na verdade, um método de custo ALTO (não baixo) e o diagnóstico da CMH é primariamente clínico/ecocardiográfico — a genética é complementar, não a ferramenta diagnóstica mais barata.
• D) O genótipo não prediz, na prática clínica atual, qual paciente responderá melhor a betabloqueador — essa decisão é guiada pela resposta clínica e hemodinâmica.
• E) O teste genético NÃO deve ser usado de rotina em todos os pacientes; é reservado para casos selecionados (diagnóstico incerto, planejamento familiar, rastreamento em cascata), dado seu custo e a frequência de variantes de significado incerto.'),

('2509394a-5392-48c0-9737-34f1da790e6a', 'Miocárdio', 2020, 'TEC', 'Considerando a apresentação clínica e o tratamento da miocardiopatia hipertrófica, escolha a afirmativa correta:', 'A fibrilação atrial é a arritmia sustentada mais comum na cardiomiopatia hipertrófica, e sua ocorrência costuma se associar a piora sintomática importante, pela perda da contração atrial em um ventrículo com relaxamento já comprometido.', 'A fibrilação atrial é, de fato, a arritmia sustentada mais frequentemente observada em pacientes com cardiomiopatia hipertrófica, favorecida pela dilatação e remodelamento atrial secundários à disfunção diastólica crônica. Sua ocorrência costuma trazer piora clínica significativa, pela perda da contribuição atrial ao enchimento ventricular, além de aumentar o risco tromboembólico (exigindo anticoagulação independentemente do escore CHA2DS2-VASc nesses pacientes).

Por que as outras alternativas estão incorretas:
• A) Em pacientes acima de 50 anos sem outros marcadores de alto risco, a mortalidade da CMH se aproxima da população geral — não permanece necessariamente maior.
• B) O CDI não deve ser indicado para "todos os pacientes" — a indicação é individualizada, baseada na estratificação de risco de morte súbita (marcadores maiores/escore de risco).
• D) A alcoolização septal reduz o gradiente, mas os resultados a longo prazo da MIOMECTOMIA cirúrgica costumam ser considerados mais duradouros/definitivos do que os da alcoolização.
• E) O marca-passo bicameral tem eficácia MODESTA na redução do gradiente e resultados INFERIORES (não comparáveis) à miomectomia cirúrgica; é reservado a casos muito selecionados.'),

('556c04a2-794a-41a5-add1-cac0ceccd2eb', 'Miocárdio', 2022, 'TEC', 'Sobre as alterações do eletrocardiograma na amiloidose cardíaca, assinale a alternativa correta:', 'A combinação de ausência de progressão de onda R nas precordiais com desproporção entre a baixa voltagem no ECG e o espessamento miocárdico ao ecocardiograma é um achado clássico e sugestivo de amiloidose cardíaca, independentemente do tipo (AL ou ATTR).', 'Um achado eletrocardiográfico clássico da amiloidose cardíaca é a chamada "desproporção eletrocardiográfica-ecocardiográfica": o ECG mostra baixa voltagem (ou, no mínimo, voltagem não aumentada) apesar do ecocardiograma revelar espessamento importante das paredes ventriculares — o que contrasta com a hipertrofia "verdadeira" (como na CMH ou hipertensiva), em que se esperaria alta voltagem. A ausência de progressão de onda R nas derivações precordiais (simulando padrão de "pseudoinfarto") também é um achado sugestivo, e ambos ocorrem tanto na amiloidose AL quanto na ATTR.

Por que as outras alternativas estão incorretas:
• A) A baixa voltagem é o achado mais citado, mas está presente em apenas uma minoria dos pacientes (mais comum na AL do que na ATTR) — não é universal nem "o mais frequente" em ambos os tipos de forma equivalente.
• B) Voltagem normal ou mesmo sinais de sobrecarga de VE PODEM ocorrer na amiloidose cardíaca (principalmente na ATTR) — não excluem o diagnóstico.
• D) A fibrilação atrial é, na verdade, MUITO comum na amiloidose cardíaca (pelo acometimento atrial extenso) e não torna o diagnóstico menos provável.
• E) O bloqueio atrioventricular de primeiro grau (e outros distúrbios de condução) é um achado COMUM (não pouco comum) na amiloidose cardíaca, pelo infiltrado amiloide no sistema de condução.'),

('3c608c00-3fda-4b76-ba2b-ee2f0d5cd2a6', 'Miocárdio', 2021, 'TEC', 'Homem, 25 anos, refere dispneia aos esforços há 1 ano. Há 1 semana, apresentou síncope desliga-liga enquanto jogava futebol. Está preocupado porque seu pai havia morrido subitamente aos 35 anos. Realizou ecocardiograma, que evidenciou: Fração de ejeção do ventrículo esquerdo normal. Septo com 30 mm. Parede posterior com 20 mm de espessura. Gradiente intraventricular de 40 mmHg. Movimento sistólico anterior da valva mitral. Ao Holter 24h, 10 episódios de taquicardia ventricular não sustentada, com até 15 batimentos. Realizou ressonância nuclear magnética, que confirmou os achados e demonstrou fibrose de 20% da massa ventricular. Assinale a alternativa correta em relação a este caso:', 'Este paciente acumula múltiplos marcadores maiores de risco (síncope inexplicada recente, espessura septal ≥30 mm, história familiar de morte súbita precoce, TVNS frequente, fibrose extensa ao realce tardio) — a conduta correta é o implante de CDI para prevenção primária de morte súbita.', 'Este paciente com cardiomiopatia hipertrófica acumula uma quantidade excepcional de marcadores maiores de risco para morte súbita: síncope recente e inexplicada (em pleno esforço), história familiar de morte súbita precoce (pai aos 35 anos), espessura septal extrema (30 mm, ≥ critério de 30 mm), TVNS frequente e repetitiva no Holter, e extensa fibrose miocárdica (20% da massa ventricular) ao realce tardio da ressonância. Diante desse acúmulo de fatores de altíssimo risco, a conduta correta é o implante de cardiodesfibrilador implantável (CDI) para prevenção primária de morte súbita cardíaca.

Por que as outras alternativas estão incorretas:
• A) A CMH pode se manifestar em qualquer idade, e o rastreamento familiar com ECG/ecocardiograma deve ser seriado ao longo da vida (não só na infância) — exames normais na idade escolar NÃO descartam a doença, que pode se expressar mais tarde.
• B) Betabloqueadores e bloqueadores de canal de cálcio NÃO são contraindicados na CMH — pelo contrário, são a base do tratamento farmacológico dos sintomas.
• C) Não há indicação de miectomia baseada apenas no gradiente moderado (40 mmHg) sem sintomas refratários ao tratamento farmacológico — a prioridade neste caso é a prevenção de morte súbita (CDI), não a redução septal.
• D) A droga de escolha para controle de ritmo da fibrilação atrial na CMH é a amiodarona, não a propafenona (que é evitada em cardiopatia estrutural).'),

('1f7d3184-0ab2-4ecf-92f9-586cb8d4df47', 'Miocárdio', 2019, 'TEC', 'Baseando-se nas recomendações e níveis de evidência para métodos complementares no diagnóstico e prognóstico na Doença de Chagas crônica, assinale o método NÃO recomendado:', 'A coronariografia não é um exame rotineiramente recomendado apenas pela combinação de precordialgia com bloqueio de ramo direito + hemibloqueio anterossuperior esquerdo — esses achados eletrocardiográficos são típicos da própria cardiopatia chagásica, e não indicam por si só investigação coronariana invasiva.', 'Na Doença de Chagas crônica, o BCRD associado a bloqueio divisional anterossuperior esquerdo é um achado eletrocardiográfico extremamente característico da própria cardiopatia chagásica (por acometimento preferencial do sistema de condução), não sendo indicação isolada de coronariografia. A investigação coronariana invasiva na Doença de Chagas é reservada para quando há suspeita real de doença arterial coronariana concomitante (fatores de risco, quadro anginoso típico, alterações isquêmicas mais específicas), não apenas pela presença desses distúrbios de condução associados à precordialgia atípica.

Por que as outras alternativas SÃO recomendadas (não são a resposta, que busca a NÃO recomendada):
• A) ECG é recomendado mesmo em pacientes assintomáticos com exame físico normal, como parte da avaliação inicial de todo chagásico (para classificação da forma da doença).
• B) Ecocardiograma é recomendado em paciente sintomático com ECG alterado, para avaliar função ventricular e forma da cardiopatia.
• D) Holter é recomendado mesmo em paciente assintomático com ECG normal quando há disfunção ventricular e alteração segmentar ao ecocardiograma, pela relevância prognóstica de arritmias ventriculares ocultas nessa população.
• E) Estudo eletrofisiológico é recomendado em sobrevivente de parada cardíaca com fração de ejeção reduzida, para orientar terapêutica antiarrítmica/indicação de CDI.'),

('7e6b6cdb-f960-43d2-9536-3591febb4346', 'Miocárdio', 2019, 'TEC', 'Homem, 76 anos, foi admitido para investigação e manejo da insuficiência cardíaca descompensada. Negava dor torácica e relatava ter coronariografia normal. Eletrocardiograma (ECG) mostrou baixa voltagem dos complexos QRS e bloqueio de ramo esquerdo. O estudo ecocardiográfico mostrou fração de ejeção preservada com espessamento parietal difuso e granulações de aspecto cintilante no miocárdio do ventrículo esquerdo associado a aumento biatrial com padrão de enchimento do ventrículo esquerdo (VE) do tipo restritivo. Assinale a alternativa INCORRETA acerca dos achados ecocardiográficos característicos dessa patologia:', 'O padrão clássico de strain (speckle-tracking) na amiloidose cardíaca é o "apical sparing" (relativa preservação da deformação no ápice com redução da deformação basal), e não hipocinesia apical — por isso essa é a alternativa incorreta.', 'O quadro descrito (baixa voltagem com espessamento parietal difuso, "aspecto cintilante"/granular do miocárdio, aumento biatrial e padrão restritivo de enchimento) é clássico de amiloidose cardíaca. O achado característico ao strain por speckle-tracking na amiloidose NÃO é hipocinesia apical, mas sim o padrão de "apical sparing": a deformação longitudinal está reduzida nos segmentos basais e médios, com relativa preservação (poupança) da deformação no ápice — o inverso do descrito na alternativa C, que por isso é a INCORRETA pedida.

Por que as outras alternativas estão corretas (não são a resposta, já que a pergunta pede a incorreta):
• A) Espessamento do septo associado a baixas voltagens no ECG é, de fato, a clássica "desproporção eletrocardiográfica-ecocardiográfica" da amiloidose.
• B) Discreto derrame pericárdico é, de fato, um achado frequente e inespecífico na amiloidose cardíaca.
• D) Espessamento da parede livre do ventrículo direito é, de fato, um achado característico, refletindo o acometimento infiltrativo biventricular.
• E) Espessamento valvar difuso (mitral e aórtico) é, de fato, achado comum pelo depósito amiloide nos folhetos valvares.'),

('b3ac8814-1e7d-4c11-9d54-ad4cbdf7569a', 'Miocárdio', 2017, 'TEC', 'Um dilema diagnóstico pode surgir ao distinguir-se clinicamente a hipertrofia fisiológica do ventrículo esquerdo (como consequência do treinamento atlético), das condições patológicas como a miocardiopatia hipertrófica. Dos parâmetros abaixo descritos, o que mais favorece o diagnóstico de coração de atleta é:', 'Uma cavidade do ventrículo esquerdo excedendo 55 mm de diâmetro favorece fortemente o diagnóstico de coração de atleta, já que na CMH a cavidade costuma ser pequena/normal (a hipertrofia "ocupa espaço" na cavidade, e não a dilata).', 'Um dos principais parâmetros ecocardiográficos que ajudam a diferenciar o "coração de atleta" (hipertrofia fisiológica) da cardiomiopatia hipertrófica é o diâmetro diastólico do ventrículo esquerdo: no coração de atleta, é comum encontrar uma cavidade VE aumentada (excedendo 55 mm), refletindo uma adaptação harmônica ao treinamento (hipertrofia excêntrica com dilatação proporcional); já na CMH, a cavidade costuma ser normal ou até reduzida, pois a hipertrofia é predominantemente concêntrica/assimétrica e não se acompanha de dilatação da câmara.

Por que as outras alternativas favorecem CMH (não coração de atleta):
• A) Um VO2 máximo BAIXO (< 30 mL/kg/min) sugere, na verdade, capacidade cardiorrespiratória reduzida, mais compatível com doença cardíaca (CMH) do que com o condicionamento de um atleta — atletas costumam ter VO2 máximo elevado.
• B) Arritmias ventriculares frequentes e sustentadas são acometimento patológico, sugerindo CMH, não achado esperado no coração de atleta saudável.
• C) Espessura parietal > 20 mm raramente é vista em atletas (que raramente excedem 16 mm) e é fortemente sugestiva de CMH.
• E) Hipertrofia com distribuição desigual/assimétrica entre diferentes regiões da parede do VE é típica da CMH (hipertrofia geneticamente determinada e heterogênea), enquanto no coração de atleta a hipertrofia tende a ser mais concêntrica e simétrica.'),

('b3883a90-8370-4915-bb9d-a4ca7602d2f7', 'Miocárdio', 2018, 'TEC', 'Paciente do sexo masculino, 30 anos, corredor amador (faz provas de 21 km e está em preparo para sua primeira maratona). Histórico de síncope esforço-induzida, histórico familiar de morte súbita de tio e primo. Eletrocardiograma (ECG) com padrão de sobrecarga de ventrículo esquerdo e ondas T invertidas profundas simétricas em parede anterior. Ecocardiograma com espessura septal = 20 mm e parede posterior = 12 mm, com fração de ejeção de ventrículo esquerdo normal e gradiente sistólico na via de saída do ventrículo esquerdo = 30 mmHg. Considerando o quadro descrito e sua principal suspeita diagnóstica, assinale a assertiva CORRETA:', 'A combinação de síncope ao esforço + história familiar de morte súbita + hipertrofia assimétrica com ondas T invertidas profundas é altamente sugestiva de cardiomiopatia hipertrófica — principal causa de morte súbita em atletas jovens.', 'A combinação de síncope induzida pelo esforço, história familiar de morte súbita em parentes jovens, e hipertrofia septal assimétrica (20 mm vs. 12 mm da parede posterior) com ondas T invertidas profundas e simétricas na parede anterior (um padrão eletrocardiográfico associado a formas apicais/atípicas de CMH) aponta fortemente para cardiomiopatia hipertrófica — reconhecida como a principal causa estrutural de morte súbita cardíaca em atletas jovens, justamente por poder permanecer assintomática até um evento fatal durante o esforço físico intenso.

Por que as outras alternativas estão incorretas:
• B) Não há elementos (histórico de hipertensão arterial de longa data, por exemplo) que sustentem cardiomiopatia hipertensiva como principal suspeita num atleta jovem de 30 anos.
• C) Mesmo estando sintomático (síncope), a alcoolização septal não é indicada de imediato sem antes confirmar o diagnóstico e tentar otimizar o tratamento farmacológico — a indicação de terapia invasiva depende de refratariedade, não é automática pela sintomatologia isolada.
• D) A apresentação (jovem atleta, hipertrofia septal assimétrica, sem outros achados típicos de amiloidose como baixa voltagem ou desproporção ECG-eco) não favorece amiloidose como suspeita principal.
• E) Embora seja verdade que a utilidade da análise genética na estratificação de risco ainda tenha limitações, essa afirmação não substitui reconhecer a CMH como a hipótese diagnóstica principal, que é o cerne da pergunta.'),

('f8a325f5-3524-4978-b12b-137475a4baea', 'Miocárdio', 2017, 'TEC', 'A miocardiopatia hipertrófica é a mais comum das doenças cardiovasculares genéticas, causada por diversas mutações em genes que codificam proteínas dos sarcômeros cardíacos. Sobre as características dessa miocardiopatias, é INCORRETO afirmar que:', 'A cardiomiopatia hipertrófica tem padrão de herança autossômica DOMINANTE (não recessiva) na grande maioria dos casos — por isso essa é a alternativa incorreta.', 'A cardiomiopatia hipertrófica é, na esmagadora maioria dos casos familiares, uma doença de herança autossômica DOMINANTE, causada por mutações em genes que codificam proteínas do sarcômero cardíaco (como MYH7 e MYBPC3, os mais frequentes). Afirmar que o padrão é autossômico recessivo está, portanto, INCORRETO.

Por que as outras alternativas estão corretas (não são a resposta, já que a pergunta pede a incorreta):
• B) Cerca de 30% dos pacientes com CMH apresentam, de fato, a forma não obstrutiva (sem gradiente significativo na via de saída em repouso ou com manobras).
• C) O gradiente subaórtico dinâmico e o sopro sistólico de ejeção são, de fato, tipicamente variáveis/dinâmicos, mudando com a pré-carga, pós-carga e contratilidade.
• D) É, de fato, comum que a hipertrofia se desenvolva ao longo de um período de latência variável (frequentemente na adolescência/estirão de crescimento), e não estar presente desde o nascimento.
• E) Histologicamente, os miócitos hipertróficos na CMH mostram, de fato, aumento do diâmetro transversal, formas bizarras e desarranjo (disarray) miofibrilar, mantendo conexões intercelulares anômalas com múltiplas células adjacentes.'),

('aeaa7d53-1ec3-421a-9165-629f0523613b', 'Miocárdio', 2018, 'TEC', 'Assinale a alternativa CORRETA acerca dos achados na miocardiopatia hipertrófica com obstrução dinâmica na via de saída do ventrículo esquerdo:', 'Manobras que reduzem a pré-carga (ficar em pé, Valsalva) diminuem o volume da cavidade do VE, aumentando o gradiente dinâmico e a intensidade do sopro, que é mais audível na borda esternal esquerda baixa e não irradia para as carótidas (ajudando a diferenciar da estenose aórtica valvar).', 'Na cardiomiopatia hipertrófica obstrutiva, manobras que reduzem a pré-carga (ficar em pé abruptamente) ou a pós-carga (Valsalva, fase de esforço) diminuem o volume diastólico final do ventrículo esquerdo. Como a obstrução dinâmica é agravada por cavidades menores (o septo hipertrofiado se aproxima mais do folheto anterior da mitral, favorecendo o movimento anterior sistólico), essas manobras aumentam o gradiente e a intensidade do sopro sistólico — que classicamente é mais bem auscultado na borda esternal esquerda baixa e, diferentemente da estenose aórtica valvar, NÃO irradia para as carótidas, um detalhe semiológico importante no diagnóstico diferencial.

Por que as outras alternativas estão incorretas:
• A) É o inverso: no teste ergométrico, uma resposta pressórica ANORMAL — elevação insuficiente (≤ 20 mmHg) ou queda da PA sistólica com o esforço — indica MAIOR (não menor) risco de morte súbita.
• B) O gradiente de repouso que caracteriza a forma obstrutiva é ≥ 30 mmHg (não ≤ 30 mmHg); o ecocardiograma é essencial, mas o valor de corte citado está invertido.
• D) O realce tardio na CMH ocorre por fibrose intersticial/de substituição, com padrão em MEIO da parede (mesocárdico, em manchas), não por acúmulo intracelular de gadolínio — o gadolínio é um agente extracelular.
• E) O verapamil é usado para sintomas na CMH, mas a alternativa erra ao dizer que ele é "especialmente" benéfico na obstrução — bloqueadores de canal de cálcio não di-idropiridínicos devem ser usados com cautela na obstrução grave, pelo efeito vasodilatador que pode piorar o gradiente; betabloqueadores são a primeira linha para reduzir o gradiente ao esforço.'),

('34df4198-c6d9-40e6-8028-0f03c50fb3dc', 'Miocárdio', 2016, 'TEC', 'Em relação à investigação diagnóstica de paciente com suspeita de miocardite, é CORRETO afirmar que:', 'A ressonância magnética cardíaca é especialmente útil em pacientes com suspeita de miocardite fulminante e instabilidade hemodinâmica, ajudando a caracterizar o processo inflamatório mesmo quando a biópsia não é imediatamente viável.', 'A ressonância magnética cardíaca (utilizando os critérios de Lake Louise — edema, hiperemia/realce precoce e realce tardio) é uma ferramenta especialmente útil na avaliação de pacientes com suspeita de miocardite, incluindo as formas fulminantes com instabilidade hemodinâmica, ajudando a caracterizar a extensão e o padrão do processo inflamatório miocárdico e a orientar a necessidade de biópsia.

Por que as outras alternativas estão incorretas:
• B) A biópsia endomiocárdica do VE é reservada para casos selecionados (miocardite fulminante, suspeita de causas com tratamento específico como miocardite de células gigantes ou sarcoidose), mas NÃO se restringe apenas a "processos definitivamente limitados a essa cavidade" — essa não é a indicação clássica de biópsia.
• C) A cintilografia com gálio-67 não é o exame recomendado para o diagnóstico de miocardite na prática atual (foi substituída por ressonância cardíaca), e não há essa recomendação específica para quadros com mais de 3 meses de evolução.
• D) Diferentemente das síndromes coronarianas agudas (curva típica de subida e queda dos marcadores), na miocardite a elevação dos marcadores de necrose costuma ser mais prolongada/persistente e menos previsível, sem seguir o padrão habitual de uma SCA.
• E) O ECG DEVE ser realizado rotineiramente na suspeita de miocardite (é parte da avaliação inicial obrigatória), podendo mostrar alterações inespecíficas de repolarização, bloqueios ou até padrão de pseudoinfarto, com relevância clínica e não sem valor prognóstico.'),

('23098886-907f-4bcb-96a3-1e5927f34f8e', 'Miocárdio', 2017, 'TEC', 'As miocardiopatias são definidas de forma tradicional com base em fenótipos estruturais e funcionais. Dos tipos abaixo descritos, a que NÃO é considerada uma dessas formas é a:', 'A classificação fenotípica tradicional das miocardiopatias inclui dilatada, hipertrófica, restritiva e arritmogênica do ventrículo direito — a forma "isquêmica" não é uma categoria fenotípica primária, e sim uma etiologia que pode originar um fenótipo dilatado.', 'A classificação fenotípica tradicional (estrutural/funcional) das miocardiopatias reconhece quatro grandes categorias: dilatada, hipertrófica, restritiva e arritmogênica do ventrículo direito (além da não classificada, categoria posterior). A cardiomiopatia "isquêmica" não é, por si só, um fenótipo dessa classificação — ela é uma ETIOLOGIA (doença arterial coronariana) que tipicamente resulta no fenótipo dilatado, sendo por isso a alternativa que não corresponde a uma das formas fenotípicas tradicionais.

Por que as outras alternativas SÃO formas fenotípicas reconhecidas (não são a resposta pedida):
• A) Dilatada é um dos quatro fenótipos clássicos.
• B) Restritiva é um dos quatro fenótipos clássicos.
• D) Hipertrófica é um dos quatro fenótipos clássicos.
• E) Arritmogênica do ventrículo direito é um dos quatro fenótipos clássicos.'),

('1815986a-9f76-43a5-a083-c87577b5d065', 'Miocárdio', 2018, 'TEC', 'Assinale a alternativa CORRETA acerca dos aspectos relativos às várias etiologias de miocardiopatia restritiva.', 'Na hemocromatose, o prognóstico depende fortemente da precocidade do diagnóstico: iniciar sangrias terapêuticas antes da instalação de fibrose/dano cardíaco irreversível pode melhorar a disfunção cardíaca e reduzir morbimortalidade.', 'Na hemocromatose, o prognóstico cardiovascular está diretamente relacionado à precocidade do diagnóstico e início do tratamento. As flebotomias terapêuticas (sangrias), ao remover o excesso de ferro antes que se estabeleça fibrose miocárdica irreversível, podem levar a melhora significativa da função cardíaca e redução da morbidade e mortalidade — por isso o diagnóstico precoce é tão determinante no desfecho desses pacientes.

Por que as outras alternativas estão incorretas:
• B) Na amiloidose AL (cadeia leve, não familiar), a polineuropatia/neuropatia autonômica pode preceder o quadro cardíaco, mas a alternativa descreve isso como sendo da "forma familiar" — a forma familiar é a hereditária por transtirretina (ATTRv), não a AL; além disso, na ATTRv HÁ, sim, espaço para transplante hepático (fonte da TTR mutante), contrariando o texto.
• C) A sarcoidose cardíaca caracteriza-se por granulomas NÃO caseosos (não caseosos é a marca histológica clássica da sarcoidose, diferente da tuberculose); e distúrbios de condução (incluindo BAV) SÃO frequentes na sarcoidose cardíaca, contrariamente ao afirmado.
• D) A endomiocardiofibrose tipicamente ACOMETE (não poupa) os ápices ventriculares — é justamente essa localização apical fibrótica que caracteriza a doença.
• E) O diagnóstico de miocardiopatia restritiva associa-se a átrios AUMENTADOS (não pequenos) ao ecocardiograma, refletindo a dificuldade de enchimento ventricular com pressões atriais elevadas.'),

('dabd86f3-10f6-4cf8-b0b7-df2726ffec42', 'Miocárdio', 2021, 'TEC', 'A cardiomiopatia por estresse (síndrome de Takotsubo) é mais frequentemente associada a:', 'A Takotsubo costuma se apresentar com dor torácica, supra de ST e inversão de onda T — mimetizando uma síndrome coronariana aguda, e por isso exige diagnóstico diferencial obrigatório com esta (incluindo cateterismo para excluir obstrução coronariana).', 'A cardiomiopatia de Takotsubo classicamente se manifesta com um quadro clínico e eletrocardiográfico que mimetiza uma síndrome coronariana aguda: dor torácica, supradesnivelamento do segmento ST (mais comumente anterior) e, na evolução, inversão de onda T, associados a elevação (geralmente discreta, desproporcional à extensão da disfunção) de marcadores de necrose miocárdica. Por essa apresentação, o diagnóstico diferencial com SCA é sempre obrigatório, geralmente exigindo cateterismo cardíaco para excluir obstrução coronariana significativa antes de confirmar o diagnóstico de Takotsubo.

Por que as outras alternativas estão incorretas:
• A) A disfunção ventricular na Takotsubo é tipicamente APICAL (o padrão mais clássico, "balonismo apical"), não predominantemente da parede inferior.
• C) A Takotsubo ocorre, por definição, na AUSÊNCIA de doença coronariana obstrutiva significativa que explique a extensão da disfunção — não há ruptura de placa/trombo como mecanismo central.
• D) É mais comum em MULHERES (não homens), especialmente na pós-menopausa (faixas etárias acima, não abaixo, dos 50 anos).
• E) Tipicamente HÁ elevação (ainda que discreta) dos marcadores de necrose miocárdica, e também elevação dos peptídeos natriuréticos (BNP/NT-proBNP) — a alternativa erra ao afirmar ausência de elevação dos marcadores.'),

('e9b0a3f2-008f-487a-9ada-e62519fbe04c', 'Miocárdio', 2017, 'TEC', 'Em relação à cardiomiopatia arritmogênica do ventrículo direito (CAVD), podemos afirmar que:', 'A CAVD costuma se manifestar entre a adolescência e os 40 anos de idade, sendo uma causa importante de morte súbita em jovens e atletas.', 'A cardiomiopatia arritmogênica do ventrículo direito (CAVD) é uma doença genética do desmossomo que tipicamente se manifesta entre a adolescência e a quarta década de vida (até os 40 anos), sendo uma causa relevante de morte súbita cardíaca em jovens, particularmente atletas, nos quais o esforço físico pode precipitar arritmias ventriculares malignas.

Por que as outras alternativas estão incorretas:
• A) A biópsia endomiocárdica na CAVD tem, na verdade, ALTA taxa de resultados falso-negativos, pois o acometimento é predominantemente epicárdico/tipo "patchy" (em remendos) e a biópsia costuma ser feita no septo (mais preservado), não capturando a área doente.
• B) A progressão para insuficiência cardíaca franca ocorre em uma MINORIA (não na maioria) dos pacientes com CAVD; a manifestação predominante é arrítmica.
• D) É o inverso: a MAIORIA (não uma minoria) dos pacientes que sofrem morte súbita por CAVD tem histórico de síncope prévia, o que reforça o valor prognóstico desse sintoma como sinal de alarme.
• E) O acometimento característico da CAVD é predominantemente do VENTRÍCULO DIREITO (não do esquerdo), com substituição fibrogordurosa — embora formas biventriculares/de predomínio esquerdo sejam reconhecidas, não é essa a descrição clássica "em especial no ventrículo esquerdo".'),

('8a62c8f7-92b4-423e-ba75-3588a702402d', 'Miocárdio', 2021, 'TEC', 'Homem, 35 anos, admitido em unidade de emergência com eletrocardiograma evidenciando (ECG) taquicardia ventricular sustentada monomórfica, morfologia de bloqueio do ramo esquerdo, sem comprometimento hemodinâmico. Após cardioversão, observa-se a presença de onda épsilon e ondas t invertidas em derivações precordiais direitas ao eletrocardiograma. O ecocardiograma mostra alteração segmentar do ventrículo direito, e a ressonância magnética confirma esse achado, além de identificar a disfunção do ventrículo direito (fração de ejeção 30%). O Holter 24h registra em torno de 5.000 extrassístoles ventriculares e vários episódios de taquicardia ventricular não sustentada. Em relação ao caso descrito, qual a alternativa correta?', 'O quadro (TV sustentada com morfologia de BRE, onda épsilon, disfunção de VD) é diagnóstico de CAVD — já com TV sustentada documentada, há indicação clara de CDI para prevenção (secundária) de morte súbita.', 'Este caso é diagnóstico de cardiomiopatia arritmogênica do ventrículo direito (CAVD): taquicardia ventricular monomórfica com morfologia de bloqueio de ramo esquerdo (origem no VD), onda épsilon (um achado eletrocardiográfico quase patognomônico, refletindo condução retardada no VD doente), ondas T invertidas nas precordiais direitas, e disfunção segmentar/global do VD confirmada por eco e ressonância. Como o paciente já apresentou TV sustentada (evento arrítmico maior), há indicação de CDI como prevenção secundária de morte súbita cardíaca, uma vez que esses pacientes têm risco elevado de recorrência e de eventos fatais.

Por que as outras alternativas estão incorretas:
• B) iECA/BRA são úteis no tratamento sintomático da disfunção ventricular associada, mas não há evidência de que mudem a evolução/prognóstico específico da CAVD como fazem em outras cardiomiopatias.
• C) Betabloqueadores NÃO são contraindicados na CAVD — pelo contrário, são parte importante do tratamento antiarrítmico; bloqueios AV não são uma característica típica da doença (que afeta predominantemente o miocárdio, não o sistema de condução AV).
• D) Diuréticos de alça e antagonistas da aldosterona PODEM ser usados normalmente no tratamento da insuficiência cardíaca associada à CAVD; não há essa contraindicação.
• E) O padrão de herança mais comum na CAVD é AUTOSSÔMICO DOMINANTE (não recessivo), com penetrância variável.'),

('1c2a9742-6b75-431d-877b-b7371efe8e1d', 'Miocárdio', 2018, 'TEC', 'Paciente do sexo feminino, 50 anos de idade, refere que há 2 anos, em exame de rotina, foi detectado pequeno aumento de creatinina sérica. Fez investigação naquela época, sem ser detectada etiologia, sendo que, na evolução, os níveis voltaram aos valores normais. Há 6 meses, começou a ter dispneia e cansaço a grandes esforços, com piora há 15 dias, quando começou a ter tosse seca. Nega doenças anteriores e não tem história familiar de hipertensão arterial sistêmica ou diabetes melito. Ao exame físico: bom estado geral, corada, hidratada, acianótica, anictérica, eupneica. Pressão arterial (PA) = 90 x 60 mmHg; frequência cardíaca (FC) = 90 bpm, rítmico; frequência respiratória (FR) = 24 resp/min. Pescoço: estase jugular 2+/4+ a 45°; à ausculta cardíaca: bulhas rítmicas normofonéticas, sem sopros; à ausculta pulmonar: estertores crepitantes em base direita; abdômen: fígado palpável a 5 cm do rebordo costal direito, borda lisa, indolor; membros inferiores sem edema. Creatinina atual = 1,82 mg/dL; filtração glomerular = 31 mL/min/1,73 m2. O eletrocardiograma mostra diminuição de amplitude de complexos QRS em plano frontal. O ecocardiograma mostra septo interventricular = 12 mm; parede posterior do ventrículo esquerdo = 12 mm; volume de átrio esquerdo = 45 mL/m2; ventrículo esquerdo de diâmetro normal; fração de ejeção de ventrículo esquerdo normal; função diastólica com padrão restritivo de grau 3; sem reversão com manobra de Valsalva.
Assinale a alternativa CORRETA em relação ao diagnóstico diferencial.', 'A combinação de baixa voltagem no ECG, espessamento discreto biventricular, disfunção diastólica restritiva grave e comprometimento renal levanta alta suspeita de amiloidose cardíaca — deve-se investigar com eletroforese/imunofixação de proteínas e considerar RM cardíaca com pesquisa de realce tardio subendocárdico.', 'Este caso combina achados sistêmicos e cardíacos sugestivos de amiloidose: baixa voltagem no ECG desproporcional ao discreto espessamento parietal (12 mm) ao ecocardiograma, disfunção diastólica restritiva grave (grau 3) sem reversão com Valsalva, dilatação atrial e — fora do coração — histórico de disfunção renal transitória inexplicada (um órgão frequentemente acometido pela amiloidose). A investigação correta inclui eletroforese de proteínas plasmáticas e imunofixação sérica/urinária (para pesquisa de cadeias leves monoclonais, screening de amiloidose AL) e ressonância magnética cardíaca, que na amiloidose tipicamente mostra realce tardio subendocárdico difuso (padrão característico dessa doença infiltrativa).

Por que as outras alternativas estão incorretas:
• B) O diagnóstico de CMH exige hipertrofia mais pronunciada e tipicamente assimétrica; 12 mm é uma espessura discreta/normal-limítrofe, insuficiente para caracterizar cardiomiopatia hipertrófica.
• C) A endomiocardiofibrose é uma hipótese menos provável nesta faixa etária/perfil clínico (mais associada a regiões tropicais endêmicas e apresentação diferente) e não explica o comprometimento renal history.
• D) A cintilografia com pirofosfato NÃO é patognomônica de amiloidose de cadeias leves — na verdade, ela é característica (e mais específica) para amiloidose por TRANSTIRRETINA (ATTR), podendo ser falso-positiva na AL.
• E) Não há descrição de ausculta cardíaca "normal" sendo argumento reforçador de endomiocardiofibrose de forma consistente com o quadro (a EMF tipicamente cursa com sopros de insuficiência valvar por comprometimento subvalvar, e a via de saída não é o local primário de acometimento).'),

('5a3ec403-a095-45fd-bdb5-0a85d5d8db95', 'Miocárdio', 2021, 'TEC', 'Homem, 45 anos, evolui com dispneia aos grandes esforços e durante avaliação cardiológica apresenta eletrocardiograma com bloqueio do ramo direito e ecocardiograma com a presença de trabéculas na parede ventricular esquerda, com localização apical dos músculos papilares; as trabéculas têm a mesma ecogenicidade do miocárdio, apresentam movimento sincrônico com a contração ventricular e os espaços intratrabeculares são preenchidos por sangue, proveniente da cavidade ventricular. Estes achados são consistentes com o diagnóstico de:', 'A descrição — trabeculado proeminente na parede do VE, com a mesma ecogenicidade e movimento sincrônico ao miocárdio compacto, e espaços intertrabeculares perfundidos pelo sangue da cavidade ventricular — é a definição clássica de miocárdio não compactado.', 'A descrição ecocardiográfica apresentada (trabéculas proeminentes com a mesma ecogenicidade do miocárdio, movimento sincrônico com a contração ventricular, e espaços intratrabeculares comunicantes com a cavidade ventricular, perfundidos pelo fluxo sanguíneo intracavitário) é a definição clássica e os critérios diagnósticos ecocardiográficos do miocárdio não compactado (cardiomiopatia/miocárdio ventricular não compactado), uma anomalia do desenvolvimento embriológico da compactação miocárdica.

Por que as outras alternativas estão incorretas:
• A) A endomiocardiofibrose caracteriza-se por fibrose endocárdica que obliteral a ponta do ventrículo, não por trabeculado proeminente com fluxo sanguíneo nos espaços intertrabeculares.
• B) A cardiomiopatia hipertrófica caracteriza-se por espessamento miocárdico difuso/assimétrico, não pela presença de trabeculado excessivo com as características descritas.
• D) A cardiomiopatia dilatada caracteriza-se por dilatação de câmaras com disfunção sistólica, sem essa descrição específica de trabeculado proeminente comunicante.
• E) A cardiomiopatia chagásica tipicamente cursa com aneurisma apical, alterações segmentares e distúrbios de condução, não com o padrão trabecular descrito.'),

('e9e58b71-55e1-432e-bd6d-cf4b8bd6216d', 'Miocárdio', 2019, 'TEC', 'Assinale a alternativa correta acerca dos aspectos relativos às várias etiologias de cardiomiopatia restritiva:', 'A amiloidose cardíaca deve ser sempre considerada no diagnóstico diferencial de pacientes com insuficiência cardíaca e fração de ejeção preservada, especialmente quando há espessamento parietal desproporcional aos fatores de risco usuais para hipertrofia.', 'A amiloidose cardíaca é uma causa importante e subdiagnosticada de insuficiência cardíaca com fração de ejeção preservada (ICFEp), devendo sempre entrar no diagnóstico diferencial desses pacientes — especialmente quando há espessamento ventricular desproporcional à história de hipertensão, achados extracardíacos sugestivos (síndrome do túnel do carpo bilateral, neuropatia, disautonomia) ou baixa voltagem eletrocardiográfica desproporcional ao espessamento parietal.

Por que as outras alternativas estão incorretas:
• A) Na amiloidose por transtirretina (m-TTR), NÃO se usa quimioterapia — o tratamento visa estabilizar a proteína (tafamidis) ou silenciar sua produção hepática; quimioterapia dirigida a clones de células B é o tratamento da amiloidose AL (cadeias leves), não da ATTR.
• B) A doença de Fabry relaciona-se à deficiência da enzima ALFA-galactosidase A (não beta-galactosidase) e tem herança ligada ao X (não autossômica dominante).
• D) A hemocromatose primária (hereditária) tem herança AUTOSSÔMICA RECESSIVA (mutação no gene HFE), não dominante; e o acometimento cardíaco tende a ser mais TARDIO em relação a órgãos como fígado e pâncreas, não precoce.
• E) O PET (tomografia por emissão de pósitrons) TEM, sim, utilidade relevante no diagnóstico e seguimento da sarcoidose cardíaca, detectando inflamação ativa (captação de FDG), sendo útil inclusive para guiar terapia imunossupressora.'),

('48cd5330-df7e-45b0-9794-08d96d9ffb1f', 'Miocárdio', 2022, 'TEC', 'Paciente do sexo masculino, de 55 anos de idade, com quadro de dispneia aos pequenos esforços, apresenta o seguinte ecocardiograma. Esse paciente é portador de:', 'A combinação clínica de dispneia progressiva com o achado ecocardiográfico descrito é mais compatível com miocardiopatia dilatada e disfunção ventricular esquerda grave, associada a regurgitação mitral secundária (funcional, por remodelamento do ventrículo e do anel mitral).', 'Na miocardiopatia dilatada com disfunção sistólica grave do ventrículo esquerdo, a dilatação do ventrículo e do anel mitral, junto com o deslocamento (tethering) dos músculos papilares, leva a uma regurgitação mitral SECUNDÁRIA (também chamada funcional): a válvula mitral em si é estruturalmente normal, mas deixa de coaptar adequadamente por causa da distorção geométrica do ventrículo dilatado — diferente da regurgitação mitral primária, causada por doença intrínseca dos folhetos/cordas.

Por que as outras alternativas estão incorretas:
• A) Miocardiopatia isquêmica com função preservada não se encaixa num quadro de dispneia progressiva relevante o suficiente para gerar a apresentação e o achado de imagem descritos neste contexto de prova, que aponta para disfunção importante.
• B) Miocardiopatia hipertrófica com função preservada e regurgitação primária não é compatível com o quadro de dispneia progressiva associado a disfunção ventricular esquerda grave sugerida pelo caso.
• D) A dilatação ventricular com disfunção grave está correta, mas a regurgitação mitral nesse contexto é SECUNDÁRIA (funcional, pela distorção geométrica), não primária (estrutural).
• E) Miocardiopatia hipertrófica não é compatível com dilatação/disfunção ventricular grave, que é o padrão típico da miocardiopatia dilatada, não da hipertrófica.'),

('00c3f96e-1454-447e-80bd-816ae101a106', 'Miocárdio', 2019, 'TEC', 'Homem, 40 anos, com queixas de fraqueza, hiporexia, febre baixa, dispneia aos esforços habituais, artralgias, de início há dois meses. Refere emagrecimento de 2 kg neste período. Ao exame: corado, ictérico (+/4+), sem edemas. Sinais flogísticos nas articulações dos punhos e joelhos. Ausculta pulmonar normal. Pressão arterial (PA) = 122 x 74 mmHg; frequência cardíaca (FC) = 68 bpm. Ausculta cardíaca: hiperfonese de P2. Fígado palpável sob o rebordo costal direito, indolor, fibroelástico. Eletrocardiograma (ECG): ritmo sinusal regular, com bloqueio atrioventricular de 2º grau (Mobitz I) e ausência de alterações isquêmicas. Radiografia tórax: aumento da área cardíaca, linfadenomegalia mediastinal bilateral. Ecodopplercardiograma: aumento de câmaras cardíacas esquerdas, acinesia do segmento basal da parede septal, com fração de ejeção do ventrículo esquerdo (FEVE) = 60%, relaxamento diastólico anormal do VE. Pressão sistólica da artéria pulmonar (PSAP) = 48 mmHg. Pericárdio normal. Discreta leucocitose e elevação de bilirrubina indireta. Assinale a alternativa correta quanto ao diagnóstico e tratamento neste caso.', 'A combinação de sintomas sistêmicos, artralgias, BAV de 2º grau, linfadenomegalia mediastinal bilateral e acinesia basal septal (padrão não coronariano) é clássica de sarcoidose cardíaca — o tratamento se baseia em corticosteroides e imunossupressores.', 'Este caso reúne o padrão clássico de sarcoidose sistêmica com envolvimento cardíaco: sintomas constitucionais (febre baixa, emagrecimento, artralgias), linfadenomegalia hilar/mediastinal bilateral na radiografia, distúrbio de condução (BAV de 2º grau Mobitz I) e uma alteração segmentar da contratilidade (acinesia basal septal) sem correspondência com território coronariano, sugerindo acometimento granulomatoso focal em vez de isquêmico. A confirmação viria por imagem (TC/RM evidenciando granulomas hepáticos/pulmonares, e RM cardíaca com edema/realce tardio nas mesmas regiões de alteração segmentar), e o tratamento de base é com corticosteroides, associados a imunossupressores em casos refratários ou com maior atividade inflamatória.

Por que as outras alternativas estão incorretas:
• B) Miocardite viral (por CMV/mononucleose) não explica bem o quadro sistêmico arrastado de 2 meses com artralgias e linfadenomegalia mediastinal — quadro mais compatível com doença granulomatosa sistêmica do que infecção viral aguda.
• C) A forma aguda da miocardiopatia chagásica não é a hipótese mais provável neste perfil clínico (sem contexto epidemiológico chagásico descrito) e o realce tardio transmural não é o padrão típico esperado aqui.
• D) A endocardite infecciosa não explica a linfadenomegalia mediastinal bilateral nem as artralgias com esse padrão sistêmico; também não há descrição de sopro valvar ou fatores de risco típicos.
• E) Na amiloidose AA (secundária/reativa), os granulomas não são a manifestação esperada — a AA se deposita como amiloide reativo a doenças inflamatórias crônicas, sem formar granulomas; o quadro descrito de granulomas é característico de sarcoidose, não de amiloidose.'),

('697a832c-fd2c-4e28-8b88-446388b37bf6', 'Miocárdio', 2020, 'TEC', 'A sarcoidose é uma doença sistêmica de causas não definidas, caracterizada histologicamente por granulomas não caseosos. Com relação ao acometimento cardíaco, assinale a alternativa INCORRETA:', 'O acometimento pulmonar na sarcoidose sistêmica é, na verdade, muito COMUM (não raro), sendo a manifestação mais frequente da doença — por isso essa é a alternativa incorreta.', 'A sarcoidose é classicamente uma doença com acometimento pulmonar muito FREQUENTE — é, de fato, a manifestação mais comum da doença, caracterizada por linfadenopatia hilar bilateral, opacidades reticulares/nodulares parenquimatosas e, em casos avançados, fibrose pulmonar. Afirmar que o acometimento pulmonar é "raro" está, portanto, INCORRETO — sendo esta a alternativa pedida (a incorreta).

Por que as outras alternativas estão corretas (não são a resposta, já que a pergunta pede a incorreta):
• A) A sarcoidose pode, de fato, afetar qualquer estrutura cardíaca — átrios, ventrículos, valvas, músculos papilares e o sistema de condução.
• B) Alterações contráteis segmentares sem correspondência coronariana, com afilamento anterobasal do septo e ecogenicidade aumentada, são, de fato, achados muito sugestivos de sarcoidose cardíaca ao ecocardiograma.
• C) As imagens híbridas PET-RM são, de fato, consideradas o método de escolha atual, permitindo avaliar estrutura/função, fibrose e inflamação ativa simultaneamente.
• E) O tratamento inclui, de fato, imunossupressão para doença ativa, tratamento da insuficiência cardíaca e terapia antiarrítmica quando indicada.'),

('ea15017b-edc4-4495-9b90-a9e399d5bf32', 'Miocárdio', 2019, 'TEC', 'Assinale a alternativa correta acerca da apresentação da miocardite aguda:', 'Nas formas agudas de miocardite com dor torácica, o quadro pode mimetizar uma síndrome coronariana aguda, incluindo alterações eletrocardiográficas e elevação de marcadores de necrose miocárdica — daí a importância do diagnóstico diferencial com SCA (geralmente via coronariografia/angiotomografia normal).', 'A miocardite aguda, quando se apresenta com dor torácica, pode mimetizar de forma bastante fiel uma síndrome coronariana aguda (SCA): pode haver alterações eletrocardiográficas (supra/infra de ST, inversão de onda T) e elevação de marcadores de necrose miocárdica (troponina), tornando indispensável o diagnóstico diferencial com SCA verdadeira — geralmente confirmado pela ausência de lesões coronarianas obstrutivas na cinecoronariografia ou angiotomografia, associado a achados de ressonância cardíaca compatíveis com miocardite (critérios de Lake Louise).

Por que as outras alternativas estão incorretas:
• A) A biópsia miocárdica NÃO é indispensável/obrigatória em todo quadro sugestivo de miocardite aguda — é reservada para casos selecionados (fulminante, suspeita de causas específicas tratáveis como células gigantes ou sarcoidose), sendo a investigação inicial não invasiva (RM cardíaca) suficiente na maioria dos casos.
• B) A miocardite de células gigantes tem curso classicamente FULMINANTE e RESPONDE MAL ao tratamento convencional (tendo prognóstico pior, não melhor, do que as formas virais) — o oposto do afirmado.
• C) Na Doença de Chagas, a manifestação aguda geralmente SE RELACIONA ao grau de parasitemia/infecção sistêmica (não é independente dela), embora o quadro clínico possa, de fato, ser sutil e exigir alto índice de suspeição.
• E) Atletas com miocardite têm risco AUMENTADO (não baixo) de morte súbita durante o exercício, sendo recomendado um período de repouso mais prolongado (tipicamente cerca de 3 a 6 meses, com reavaliação) antes do retorno, não um retorno simplificado em 4-6 semanas.'),

('940d4a45-d8ce-4fa3-a6ad-e9a34306547e', 'Miocárdio', 2020, 'TEC', 'Em relação à abordagem diagnóstica da miocardite, pode-se afirmar:', 'Níveis elevados de troponinas cardíacas (I e T) associam-se à gravidade da miocardite e ao prognóstico do paciente, sendo um marcador útil de lesão miocárdica em curso.', 'Na avaliação diagnóstica da miocardite, os níveis de troponinas cardíacas (I e T) são úteis marcadores de lesão miocárdica em curso, e sua elevação (grau e persistência) se associa à gravidade do quadro e ao prognóstico do paciente, sendo utilizados tanto no diagnóstico inicial quanto no acompanhamento evolutivo.

Por que as outras alternativas estão incorretas:
• A) O NT-proBNP tende a NORMALIZAR (não permanecer elevado) após a recuperação da função ventricular — sua elevação persistente sugeriria disfunção ventricular persistente, não é uma característica esperada "sempre".
• C) Os títulos de anticorpos virais circulantes NÃO se correlacionam bem com os genomas virais encontrados no tecido miocárdico (por PCR/biópsia), e por isso NÃO são recomendados como método diagnóstico na prática clínica.
• D) Aumento da duração do QRS > 120 ms e presença de ondas Q na miocardite SÃO achados com valor prognóstico (associados a maior risco de eventos adversos, incluindo morte ou transplante), não inespecíficos e sem valor.
• E) A sensibilidade e especificidade da ressonância cardíaca para detectar realce tardio na miocardite são MAIORES quando o exame é feito PRECOCEMENTE (próximo ao início dos sintomas), não após duas semanas — o edema/inflamação aguda tende a se resolver com o tempo, reduzindo a acurácia tardia.'),

('a39c1193-735b-45da-b7bf-ea4972c55349', 'Miocárdio', 2020, 'TEC', 'Um atleta profissional de 20 anos procura avaliação cardiológica após quadro de miocardite há cerca de 15 dias, preocupado com seu retorno aos treinos. Assinale a alternativa correta em relação ao caso descrito:', 'Na miocardite aguda, existe risco de morte súbita relacionado ao esforço físico durante a fase aguda/inflamatória — por isso recomenda-se um período de repouso esportivo (tipicamente de 3 a 6 meses) antes de liberar o retorno gradual ao treino e à competição.', 'A miocardite aguda representa um período de risco aumentado de morte súbita relacionada ao esforço físico, pois o miocárdio inflamado é mais vulnerável a arritmias ventriculares malignas durante o exercício. Por isso, as diretrizes de cardiologia do esporte recomendam um período de repouso esportivo (tipicamente de 3 a 6 meses, dependendo da gravidade e normalização dos exames), com reavaliação completa (função ventricular, ausência de arritmias, normalização de marcadores) antes de liberar o retorno gradual às atividades competitivas.

Por que as outras alternativas estão incorretas:
• A) A normalização da função e das dimensões ao ecocardiograma em repouso é necessária, mas NÃO é suficiente isoladamente — a avaliação para retorno ao esporte também exige Holter/teste de esforço para excluir arritmias e, frequentemente, RM cardíaca mostrando resolução do processo inflamatório.
• B) Extrassístoles ventriculares frequentes SÃO uma contraindicação (ou pelo menos motivo de cautela/investigação adicional) para o retorno, não algo que possa ser ignorado.
• C) A biópsia miocárdica NÃO é fundamental de rotina no atleta com miocardite para definir tratamento/prognóstico — a conduta se baseia principalmente em exames não invasivos (ecocardiograma, RM, Holter).
• D) Marcadores inflamatórios e de necrose miocárdica PODEM, sim, interferir na decisão de liberação, sendo parte da avaliação seriada antes do retorno ao esporte.'),

('e279f496-5efa-4384-bd32-3f94cb36dbad', 'Miocárdio', 2019, 'TEC', 'Homem, 56 anos, com quadro de dispneia aos esforços, em caráter progressivo, relatando episódios de ortopneia e dispneia paroxística na última semana. Informa ter diagnóstico de cardiopatia, em uso de enalapril, furosemida e digoxina. Ecocardiograma realizado previamente evidenciou fração de ejeção (FE) de 36%, com ventrículo esquerdo (VE) dilatado. Cateterismo estava normal, exceto por estenose de 30% no terço médio da artéria descendente anterior. História familiar de insuficiência coronariana e passado de alcoolismo (quase um litro de bebida destilada diariamente). Exame físico evidenciou frequência cardíaca (FC) = 119 bpm; pressão arterial (PA) = 110 x 70 mmHg; frequência respiratória (FR) = 18 irpm (incursões respiratórias por minuto), com saturação de 94% em ar ambiente. Impulso cardíaco apical desviado inferior e lateralmente. B3 palpável, sem sopros. Presença de crepitações inspiratórias basais. Assinale a alternativa INCORRETA:', 'A biópsia cardíaca não é rotineiramente necessária para diagnosticar cardiomiopatia dilatada idiopática — é reservada para suspeita de causas específicas tratáveis (miocardite de células gigantes, sarcoidose, doenças de depósito) — por isso essa é a alternativa incorreta.', 'O diagnóstico de cardiomiopatia dilatada (incluindo a forma idiopática, quando causas secundárias são excluídas por história, exame físico e exames não invasivos) NÃO exige biópsia miocárdica de rotina. A biópsia é reservada para situações específicas em que uma causa tratável precisa ser confirmada ou excluída (miocardite de células gigantes, sarcoidose cardíaca, doenças de depósito), não sendo passo obrigatório antes de se atribuir o rótulo de "idiopática" — este paciente, aliás, já tem uma causa provável evidente (cardiomiopatia alcoólica pelo etilismo pesado), o que reforça ainda mais que a biópsia não seria o próximo passo indicado.

Por que as outras alternativas estão corretas (não são a resposta, já que a pergunta pede a incorreta):
• B) O padrão restritivo de disfunção diastólica é, de fato, mais comum em quadros de sobrecarga de volume na IC "descompensada", e tende a melhorar com diuréticos e vasodilatadores, refletindo a natureza hemodinâmica (não estrutural fixa) desse padrão nesse contexto.
• C) Um padrão de realce tardio não transmural, de distribuição não coronariana (mesocárdico), é, de fato, sugestivo de cardiomiopatia dilatada não isquêmica (em contraste com o padrão subendocárdico/transmural da etiologia isquêmica).
• D) A penetrância dependente da idade é, de fato, característica reconhecida da CMD familiar — portadores do alelo podem não manifestar o fenótipo até idades mais avançadas.
• E) O consumo excessivo e crônico de álcool é, de fato, causa reconhecida de cardiomiopatia dilatada — a cardiomiopatia alcoólica, fortemente sugerida neste caso pela história de etilismo pesado.'),

('2e5c751b-b592-4412-805e-63bd8d1b2d4c', 'Miocárdio', 2017, 'TEC', 'A única alternativa que NÃO corresponde a uma característica clínica e/ou métodos complementares da miocardite fulminante é:', 'A biópsia endomiocárdica é, de fato, eficaz e recomendada no diagnóstico da miocardite fulminante (ajuda a identificar formas específicas tratáveis, como células gigantes ou eosinofílica) — por isso a afirmação de que "não é eficaz" é a que não corresponde ao quadro, sendo a resposta pedida.', 'Na miocardite fulminante, a biópsia endomiocárdica é considerada uma ferramenta diagnóstica EFICAZ e recomendada: diferente de formas mais brandas/difusas em que o processo pode ser mais heterogêneo, a miocardite fulminante costuma ter um processo inflamatório mais extenso e homogêneo, aumentando o rendimento diagnóstico da biópsia, além de permitir identificar formas específicas com tratamento próprio (células gigantes, eosinofílica), o que muda diretamente a conduta terapêutica. Por isso, afirmar que "a biópsia não é eficaz para o diagnóstico" não corresponde ao quadro da miocardite fulminante, sendo esta a alternativa pedida.

Por que as outras alternativas SÃO características verdadeiras da miocardite fulminante (não são a resposta pedida):
• B) De fato, tem início abrupto, geralmente dentro de duas semanas do início de uma doença viral prodrômica.
• C) De fato, cerca de 10% dos casos de miocardite confirmada por biópsia correspondem à forma fulminante.
• D) De fato, os pacientes apresentam comprometimento hemodinâmico grave, com hipotensão e necessidade frequente de vasopressores/inotrópicos e, muitas vezes, suporte circulatório mecânico.
• E) De fato, o ecocardiograma tipicamente mostra hipocinesia global difusa, sem dilatação importante do ventrículo, e espessamento parietal por edema miocárdico agudo.'),

('1c958654-809b-4e84-886b-47fb0f4a7ed5', 'Miocárdio', 2021, 'TEC', 'Mulher, 25 anos, sem antecedentes cardiovasculares, apresenta-se com quadro de dispneia há 10 dias, com piora rapidamente progressiva, evoluindo com choque cardiogênico e necessidade de suporte inotrópico e hemodinâmico com balão intra-aórtico. Ecocardiograma revelou fração de ejeção do ventrículo esquerdo de 20%. Sobre as hipóteses diagnósticas e manejo da paciente, é correto afirmar:', 'Diante de miocardite fulminante com choque cardiogênico, o suporte circulatório mecânico (balão intra-aórtico, dispositivos de assistência ventricular ou ECMO) deve ser considerado precocemente como ponte para recuperação ou para transplante cardíaco.', 'Este quadro é típico de miocardite fulminante: início agudo (dias), evolução rápida para choque cardiogênico grave com necessidade de suporte inotrópico e mecânico. Nessa situação, o suporte circulatório mecânico (balão intra-aórtico, dispositivos de assistência ventricular ou ECMO) deve ser considerado precocemente, funcionando como ponte para a recuperação miocárdica espontânea (que ocorre em boa parte dos casos de miocardite fulminante que sobrevivem à fase aguda) ou, quando não há recuperação, como ponte para transplante cardíaco.

Por que as outras alternativas estão incorretas:
• A) A ressonância magnética é útil para caracterizar o processo inflamatório, mas NÃO define de forma confiável o agente/fator causal específico da miocardite (viral, células gigantes, eosinofílica) — essa distinção geralmente requer biópsia endomiocárdica.
• B) A biópsia endomiocárdica, na verdade, ESTÁ indicada na miocardite fulminante, justamente por poder identificar formas específicas (células gigantes, eosinofílica) que mudam radicalmente o tratamento (imunossupressão).
• D) A sobrevida após transplante cardíaco em pacientes com miocardite (incluindo de células gigantes, quando tratada) não é necessariamente PIOR do que outras etiologias — muitos estudos mostram desfechos comparáveis ou até favoráveis nesse grupo, sobretudo pela idade mais jovem dos pacientes.
• E) O tratamento imunossupressor ESTÁ indicado (e é fundamental) na miocardite de células gigantes, que tem excelente resposta à imunossupressão precoce em comparação ao curso fulminante sem tratamento.'),

('347ae61c-4c4f-42da-9ec8-6b37c7c1450c', 'Miocárdio', 2022, 'TEC', 'Em relação à Cardiomiopatia de Takotsubo, assinale a alternativa INCORRETA:', 'A presença de um gatilho de estresse físico ou emocional é típica, mas NÃO é obrigatória para o diagnóstico — casos sem gatilho identificável são reconhecidos e não excluem a síndrome — por isso essa é a alternativa incorreta.', 'Embora o gatilho de estresse físico ou emocional seja um achado típico e frequente na cardiomiopatia de Takotsubo (refletindo o papel central da hiperativação simpática/catecolaminérgica na sua fisiopatologia), a AUSÊNCIA de um gatilho identificável NÃO exclui o diagnóstico — uma parcela dos casos ocorre sem fator precipitante claro reconhecível. Por isso, afirmar que a ausência de gatilho "exclui a síndrome" está INCORRETO, sendo esta a alternativa pedida.

Por que as outras alternativas estão corretas (não são a resposta, já que a pergunta pede a incorreta):
• A) É, de fato, uma forma transitória de cardiomiopatia, geralmente após grande estresse, levando a discinesia/"balonismo" apical.
• B) De fato, frequentemente mimetiza SCA, com dor torácica, supra de ST anterior e elevação de troponina.
• C) A hiperativação simpática é, de fato, o mecanismo proposto para a combinação paradoxal de hipercontratilidade basal com discinesia/balonamento apical.
• D) O estresse físico/emocional como gatilho é, de fato, um forte argumento a favor do papel central da atividade simpática na fisiopatologia da síndrome.'),

('7eb4e3c6-f489-42a4-a29a-bc0bd04d069a', 'Miocárdio', 2021, 'TEC', 'Sobre a cardiomiopatia dilatada (CMD) é correto afirmar:', 'Mutações genéticas respondem por cerca de 35% dos casos de CMD, envolvendo genes que codificam proteínas do sarcômero, do citoesqueleto, dos desmossomos e da membrana nuclear (como a laminina A/C).', 'A cardiomiopatia dilatada tem uma parcela relevante e cada vez mais reconhecida de casos genéticos: estima-se que mutações respondam por cerca de 35% dos casos, envolvendo diversas famílias de genes — do sarcômero (como na CMH), do citoesqueleto, das proteínas desmossômicas, e da membrana nuclear (como o gene LMNA, associado a formas com distúrbios de condução e arritmias graves).

Por que as outras alternativas estão incorretas:
• A) Na miocardite como causa de CMD, os agentes infecciosos mais frequentes são VIRAIS (não fungos) — enterovírus, parvovírus B19, adenovírus, entre outros.
• B) O consumo excessivo de etanol está associado a REDUÇÃO (não aumento) da frequência cardíaca e a efeito VASODILATADOR sistêmico que, combinado à toxicidade direta, leva a prejuízo da contratilidade — mas a descrição fisiopatológica com "aumento da FC" está incorreta para o mecanismo clássico.
• C) As antraciclinas causam, sim, lesão por estresse oxidativo, mas o fenótipo resultante é predominantemente DILATADO (não hipertrófico) — cardiotoxicidade por antraciclina é causa clássica de CMD.
• D) A cardiomiopatia periparto ocorre classicamente no ÚLTIMO MÊS de gestação até os primeiros 5 meses de puerpério (não nos dois primeiros trimestres) — a alternativa inverte completamente a janela temporal característica.'),

('b6140576-d7b0-447b-8f94-6238282c45bf', 'Miocárdio', 2016, 'TEC', 'Em relação à endomiocardiofibrose, é CORRETO afirmar:', 'Na fase sintomática da endomiocardiofibrose, a sobrevida em dois anos é de aproximadamente 50%, refletindo o mau prognóstico da doença uma vez estabelecida a insuficiência cardíaca restritiva.', 'A endomiocardiofibrose é uma miocardiopatia restritiva de prognóstico reservado quando já sintomática: estima-se uma sobrevida de aproximadamente 50% em dois anos após o início dos sintomas de insuficiência cardíaca, refletindo a natureza progressiva e o tratamento clínico limitado da doença em fase avançada.

Por que as outras alternativas estão incorretas:
• A) A fibrose na endomiocardiofibrose tipicamente acomete a região apical e o aparelho valvar atrioventricular (cordas e músculos papilares), mas o "acometimento dos músculos papilares" descrito de forma isolada não capta a característica mais central da doença, que é justamente a obliteração fibrótica do ÁPICE ventricular — a formulação da alternativa A não é a mais precisa/completa.
• B) A endomiocardiofibrose costuma acometer pacientes JOVENS (crianças e adultos jovens) em regiões tropicais, não predominantemente idosos.
• D) Na patogênese da EMF, além de fatores individuais/suscetibilidade, fatores AMBIENTAIS (infecções, desnutrição, fatores socioeconômicos) têm papel reconhecido — não são "apenas" fatores individuais.
• E) O transplante cardíaco é, de fato, uma opção terapêutica, mas os resultados costumam ser considerados razoáveis nessa doença quando bem indicado — a alternativa generaliza de forma imprecisa ao dizer que os resultados "não são animadores" como regra.'),

('ed11d80a-ea7d-4c79-a84c-0c4319e433de', 'Miocárdio', 2017, 'TEC', 'Entre as cardiomiopatias específicas com fenótipo dilatado, existe a Takotsubo, uma cardiomiopatia aguda provocada por uma situação de estresse físico ou emocional ou por exposição a altas doses de catecolaminas. Das características abaixo, a que NÃO faz parte do quadro de Takotsubo é:', 'Por definição, a cardiomiopatia de Takotsubo ocorre na AUSÊNCIA de doença aterosclerótica coronariana que explique a extensão da disfunção — a presença de doença aterosclerótica associada NÃO é uma característica do quadro, sendo esta a alternativa que não corresponde à Takotsubo.', 'Um dos critérios diagnósticos centrais da cardiomiopatia de Takotsubo é justamente a AUSÊNCIA de doença arterial coronariana obstrutiva que justifique a extensão da disfunção ventricular observada (embora a coexistência de DAC não obstrutiva incidental seja possível e não exclua o diagnóstico). Por isso, "a coronariografia mostra doença aterosclerótica associada" NÃO é uma característica esperada do quadro clássico de Takotsubo, sendo a alternativa pedida.

Por que as outras alternativas SÃO características da Takotsubo (não são a resposta pedida):
• A) É, de fato, mais comum em mulheres de meia-idade/pós-menopausa.
• C) O ECG pode, de fato, simular um IAM (supra de ST, inversão de onda T), sendo um dos motivos do diagnóstico diferencial obrigatório.
• D) A disfunção ventricular regional (frequentemente apical, mas também médio-ventricular, basal ou focal) é, de fact, uma das apresentações reconhecidas.
• E) A ressonância cardíaca mostrando miocárdio viável (sem realce tardio transmural fibrótico) em áreas acinéticas é, de fato, um achado útil para diferenciar Takotsubo de infarto (que mostraria necrose/fibrose correspondente).'),

('da12f85c-ea03-4882-8f4c-c76ba17bf6a6', 'Miocárdio', 2014, 'TEC', 'Paciente do sexo feminino, 60 anos, está em tratamento para câncer de mama metastático com quimioterapia e radioterapia. Ela procura atendimento em uma emergência hospitalar com dispneia intensa, iniciada há poucas horas, acompanhada de tosse seca e lipotimia. No exame físico, observa-se uma paciente emagrecida, afebril, ausculta cardíaca com bulhas difusamente hipofonéticas, mas sem sopros, turgência jugular patológica e pulsos filiformes. Há discretas crepitações em bases pulmonares. PA = 90x50 mmHg, FC = 125 bpm e FR = 32 irpm. O melhor exame complementar a ser solicitado, nesse momento, para o diagnóstico deve ser:', 'O quadro (bulhas hipofonéticas, turgência jugular, pulso filiforme/paradoxal, hipotensão, paciente oncológica) é sugestivo de tamponamento cardíaco — o ecocardiograma transtorácico é o exame de escolha, rápido e à beira do leito, para confirmar o derrame pericárdico e seu impacto hemodinâmico.', 'O quadro clínico (bulhas cardíacas difusamente hipofonéticas, turgência jugular patológica, pulsos filiformes, hipotensão e taquicardia, numa paciente com neoplasia em tratamento — fator de risco para derrame pericárdico neoplásico) é altamente sugestivo de tamponamento cardíaco. O ecocardiograma transtorácico é o exame de escolha nesse cenário: rápido, disponível à beira do leito, permite confirmar a presença e o volume do derrame pericárdico e avaliar sinais de comprometimento hemodinâmico (colapso de câmaras direitas, variação respiratória exagerada dos fluxos), orientando a conduta de urgência (pericardiocentese).

Por que as outras alternativas estão incorretas:
• A) A radiografia de tórax pode sugerir aumento da área cardíaca ("coração em moringa"), mas não é o exame mais direto/específico para confirmar tamponamento e guiar a conduta imediata.
• C) A ressonância magnética cardíaca não é factível/indicada na urgência de uma paciente instável — é um exame demorado, inadequado para esse cenário agudo.
• D) A tomografia de tórax pode mostrar o derrame, mas não é o exame de escolha inicial na urgência à beira do leito, nem avalia tão bem o impacto hemodinâmico em tempo real como o ecocardiograma.
• E) "Pulso arterial alternante é característico de casos graves" não é um exame complementar (é um achado semiológico, e além disso mais associado a disfunção sistólica grave do que a tamponamento, cujo achado clássico é o pulso PARADOXAL, não o alternante) — não responde ao que a questão pede.'),

('9551914e-0384-4e28-98a5-06eb87ac7b37', 'Miocárdio', 2018, 'TEC', 'Paciente feminina, de 25 anos, com queixas de palpitações e precordialgia atípica. A mãe apresentava insuficiência cardíaca, com fração de ejeção reduzida. O exame físico apresentou-se normal. O eletrocardiograma mostra alterações inespecíficas da repolarização ventricular. A paciente apresenta janela ecocardiográfica limitada, com função ventricular normal, mas o ecocardiografista questiona a presença de trabéculas na ponta do ventrículo esquerdo, observando-se fluxo nas trabéculas pelo Doppler colorido. Assinale a alternativa correta em relação ao diagnóstico diferencial de miocárdio não compactado:', 'O diagnóstico diferencial de miocárdio não compactado, na ponta do VE, inclui endomiocardiofibrose, cardiomiopatia hipertrófica apical e trombos apicais — condições que também podem alterar o aspecto dessa região ao ecocardiograma.', 'A avaliação ecocardiográfica do ápice do ventrículo esquerdo, especialmente com janela acústica limitada, pode gerar confusão diagnóstica entre miocárdio não compactado verdadeiro e outras condições que também alteram o aspecto apical: a endomiocardiofibrose (fibrose endocárdica que pode obliterar/distorcer o ápice), a cardiomiopatia hipertrófica apical (hipertrofia localizada na ponta do VE, que pode ser confundida com trabeculado espessado) e trombos apicais (que podem se sobrepor a estruturas trabeculares e mimetizar seu aspecto, sobretudo quando a definição de imagem é subótima). O uso do Doppler colorido para confirmar fluxo sanguíneo nos espaços intertrabeculares, como descrito no caso, é justamente uma das formas de diferenciar o miocárdio não compactado verdadeiro de um trombo (que não teria fluxo).

Por que as outras alternativas estão incorretas:
• B) Amiloidose não é um diagnóstico diferencial clássico nesse contexto apical — ela cursa com espessamento parietal difuso e infiltrativo, não com trabeculado apical proeminente.
• C) Cardiomiopatia hipertrófica OBSTRUTIVA (via de saída/septal) não é o diagnóstico diferencial relevante para achados apicais — a forma relevante é a hipertrófica APICAL.
• D) Sarcoidose não cursa tipicamente com trabeculado apical proeminente que mimetize miocárdio não compactado.
• E) A cardiomiopatia de Takotsubo cursa com acinesia/discinesia apical TRANSITÓRIA (não com trabeculado hiperecogênico fixo), não sendo diagnóstico diferencial ecocardiográfico típico dessa apresentação.'),

('8baddc7e-b426-40d5-8f7f-00ba834e7912', 'Miocárdio', 2018, 'TEC', 'A hemocromatose é uma doença sistêmica, geneticamente determinada, resultante do excessivo acúmulo de ferro nos tecidos, notavelmente fígado, coração, gônadas e pâncreas. Há uma síndrome clínica clássica, caracterizada por insuficiência cardíaca, cirrose, impotência sexual, diabetes e artrite. Em relação à hemocromatose e suas manifestações cardiovasculares, assinale a alternativa INCORRETA:', 'Na hemocromatose são os homens (não as mulheres jovens) que costumam ter formas mais graves e precoces — a perda menstrual funciona como uma "sangria" fisiológica que retarda o acúmulo de ferro nas mulheres até a menopausa — por isso essa é a alternativa incorreta.', 'Na hemocromatose hereditária, os HOMENS tipicamente desenvolvem manifestações clínicas mais precoces e mais graves (incluindo insuficiência cardíaca) do que as mulheres, pois as perdas menstruais mensais funcionam como uma forma natural de depleção de ferro, retardando o acúmulo tecidual nas mulheres até após a menopausa. Dizer que "mulheres jovens em geral apresentam formas mais graves" é o inverso do observado na prática clínica, tornando esta a alternativa INCORRETA pedida.

Por que as outras alternativas estão corretas (não são a resposta, já que a pergunta pede a incorreta):
• B) O acometimento cardíaco produz, de fato, um padrão misto de disfunção sistólica e diastólica (podendo evoluir de um fenótipo restritivo para dilatado).
• C) As arritmias (incluindo fibrilação atrial e ventriculares, pelo depósito de ferro no sistema de condução) respondem, de fato, pela maior parte das mortes súbitas, mais comumente em homens jovens.
• D) O ecocardiograma pode, de fato, mostrar espessamento parietal, dilatação e disfunção ventricular; e ferro, ferritina e saturação de transferrina estão, de fato, tipicamente elevados (exames de triagem da doença).
• E) O tratamento envolve, de fato, flebotomias terapêuticas repetidas como primeira linha, e agentes quelantes de ferro (como a desferroxamina) quando a flebotomia não é viável.'),

('a9753463-7cd7-4de5-b183-2b4eef3a03ab', 'Miocárdio', 2018, 'TEC', 'Em relação à cardiomiopatia de Takotsubo, assinale a alternativa CORRETA:', 'A Takotsubo caracteristicamente mostra alteração da contratilidade do VE — mais comumente apical, mas também podendo ser basal, médio-ventricular ou de uma região específica — sempre na ausência de doença coronariana obstrutiva que justifique o achado.', 'A cardiomiopatia de Takotsubo caracteriza-se por uma alteração transitória e reversível da contratilidade segmentar do ventrículo esquerdo, cujo padrão mais comum é o apical ("balonismo apical"), mas que também pode assumir formas basal (Takotsubo invertida), médio-ventricular ou focal/de uma região específica — sempre ocorrendo na ausência de doença coronariana obstrutiva que explique a extensão do comprometimento contrátil observado.

Por que as outras alternativas estão incorretas:
• A) O diagnóstico diferencial mais importante e mais crítico da Takotsubo é a SÍNDROME CORONARIANA AGUDA (infarto), não a cardiomiopatia dilatada — pela apresentação clínica e eletrocardiográfica semelhante e pela necessidade de excluir obstrução coronariana aguda.
• B) O exame inicial mais indicado não é a ressonância com gadolínio de rotina — geralmente inicia-se com ecocardiograma e cinecoronariografia/angiotomografia para excluir SCA; a RM é um exame complementar útil, mas não a primeira escolha obrigatória.
• D) A recorrência da Takotsubo é, na verdade, relativamente BAIXA (a maioria dos pacientes não recorre), não alta.
• E) Vasopressores NÃO devem ser usados rotineiramente na Takotsubo — pelo contrário, como o mecanismo é de excesso catecolaminérgico, agentes adrenérgicos podem ser deletérios; prefere-se suporte com inotrópicos não catecolaminérgicos (como levosimendana) ou suporte mecânico quando necessário.');

insert into public.question_options (id, question_id, letra, texto, correta) values
(gen_random_uuid(), '91903d7c-edc9-4378-914e-fb03c2e2e2f3', 'a', 'Aneurisma ventricular, TVNS prolongada, espessura ventricular entre 11 e 15 mm.', false),
(gen_random_uuid(), '91903d7c-edc9-4378-914e-fb03c2e2e2f3', 'b', 'Espessura septal maior que 30 mm, fibrilação atrial e história familiar.', false),
(gen_random_uuid(), '91903d7c-edc9-4378-914e-fb03c2e2e2f3', 'c', 'Hipotensão ao exercício, fibrilação atrial e oligossintomáticos.', false),
(gen_random_uuid(), '91903d7c-edc9-4378-914e-fb03c2e2e2f3', 'd', 'Síncope, história familiar de cardiopatia hipertrófica e aumento do volume do átrio esquerdo.', false),
(gen_random_uuid(), '91903d7c-edc9-4378-914e-fb03c2e2e2f3', 'e', 'Taquicardia ventricular, síncope e hipotensão ao exercício.', true),

(gen_random_uuid(), '2864e426-efd9-4f25-8baf-96c0f40d24ca', 'a', 'A ressonância nuclear magnética é imperativa na investigação diagnóstica do caso descrito, pois o eletrocardiograma e o ecocardiograma não são indicativos e amiloidose cardíaca.', false),
(gen_random_uuid(), '2864e426-efd9-4f25-8baf-96c0f40d24ca', 'b', 'A imagem do strain longitudinal global mostra uma alteração de deformidade regional do ventrículo esquerdo que poupa os segmentos apicais (apical sparing), mas esse não é achado sugestivo de amiloidose cardíaca por depósito de transtirretina.', false),
(gen_random_uuid(), '2864e426-efd9-4f25-8baf-96c0f40d24ca', 'c', 'A cintilografia cardíaca com pirofosfato com tecnécio não faz parte do fluxograma diagnóstico desse paciente, visto que, com a presença de gamopatia monoclonal, o diagnóstico mais provável é o de amiloidose por cadeias leves (AL), com o seu resultado sendo possivelmente um falso positivo.', true),
(gen_random_uuid(), '2864e426-efd9-4f25-8baf-96c0f40d24ca', 'd', 'A cintilografia cardíaca com pirofosfato com tecnécio tem 100% de especificidade para o diagnóstico de amiloidose cardíaca por depósito de transtirretina, não havendo necessidade de outros exames diagnósticos para esse caso.', false),
(gen_random_uuid(), '2864e426-efd9-4f25-8baf-96c0f40d24ca', 'e', 'O achado de baixa voltagem no eletrocardiograma tem alta sensibilidade em pacientes portadores de amiloidose cardíaca por depósito de transtirretina.', false),

(gen_random_uuid(), '2297d06e-10a7-4b44-8fdd-5dda2e5b3027', 'a', 'A forma familiar frequentemente associa-se a mutações na proteína plasmática transtirretina e o transplante hepático é uma alternativa quando o diagnóstico é precoce.', false),
(gen_random_uuid(), '2297d06e-10a7-4b44-8fdd-5dda2e5b3027', 'b', 'Aproximadamente um quarto dos pacientes com a forma ligada à transtirretina experimenta significativo envolvimento cardíaco, nas formas de distúrbios de condução ou insuficiência cardíaca.', false),
(gen_random_uuid(), '2297d06e-10a7-4b44-8fdd-5dda2e5b3027', 'c', 'Outras manifestações clínicas frequentes incluem hipotensão postural, nefropatia (desde leve até franca insuficiência renal) e neuropatia (mononeuropatia múltipla, síndrome do túnel do carpo).', false),
(gen_random_uuid(), '2297d06e-10a7-4b44-8fdd-5dda2e5b3027', 'd', 'A amiloidose primária decorre de um depósito reativo de imunoglobulinas, denominado de amiloide A (AL), associada a doenças crônicas, infecciosas e inflamatórias, com boa resposta ao tratamento específico.', true),
(gen_random_uuid(), '2297d06e-10a7-4b44-8fdd-5dda2e5b3027', 'e', 'Ao exame físico, a maioria dos pacientes com amiloidose cardíaca apresenta turgência jugular, edemas, hepatomegalia. A hipofonese de B1 é típica do envolvimento atrial.', false),

(gen_random_uuid(), 'e15135e0-0180-4d49-85b5-64a450196995', 'a', 'A cardiomiopatia hipertrófica, quando é do tipo não obstrutiva, não se constitui marcador de risco para morte súbita.', true),
(gen_random_uuid(), 'e15135e0-0180-4d49-85b5-64a450196995', 'b', 'A incidência de morte súbita em crianças abaixo de 1 ano é similar à incidência em adultos de meia-idade ou mais velhos.', false),
(gen_random_uuid(), 'e15135e0-0180-4d49-85b5-64a450196995', 'c', 'A síndrome do QT longo congênito é um contribuinte genético para o risco de morte súbita.', false),
(gen_random_uuid(), 'e15135e0-0180-4d49-85b5-64a450196995', 'd', 'A doença arterial coronariana é a principal base estrutural para o risco de morte súbita.', false),
(gen_random_uuid(), 'e15135e0-0180-4d49-85b5-64a450196995', 'e', 'A morte súbita cardíaca pode ser a primeira manifestação de doença coronária em até metade dos casos.', false),

(gen_random_uuid(), '5a80acf2-75a9-4c16-8eac-b54f3dfa43c9', 'a', 'Pode-se suspeitar dessa doença ao identificar-se um sopro diastólico aórtico em avaliações de rotina. Quanto menor a obstrução dinâmica na via de saída, maior a intensidade do sopro, o qual se torna menos pronunciado com a Manobra de Valsalva.', false),
(gen_random_uuid(), '5a80acf2-75a9-4c16-8eac-b54f3dfa43c9', 'b', 'Nos casos com predomínio de hipertrofia anterolateral e apical, o ecocardiograma supera a ressonância magnética. O ecocardiograma ainda permite a estratificação de risco para morte súbita, por facilitar a caracterização de fibrose pela hiperrefringência do septo interventricular.', false),
(gen_random_uuid(), '5a80acf2-75a9-4c16-8eac-b54f3dfa43c9', 'c', 'O tratamento intervencionista da obstrução está indicado para pacientes sintomáticos refratários ao tratamento farmacológico.', true),
(gen_random_uuid(), '5a80acf2-75a9-4c16-8eac-b54f3dfa43c9', 'd', 'Os pacientes não evoluem com disfunção sistólica, remodelamento ventricular acentuado, afilamento de paredes e/ou aumento de câmaras, já que a hipertrofia ventricular impede esse processo.', false),
(gen_random_uuid(), '5a80acf2-75a9-4c16-8eac-b54f3dfa43c9', 'e', 'A alcoolização septal reduz discretamente o gradiente e melhora a sintomatologia em poucos pacientes, que frequentemente requerem tratamento cirúrgico subsequente.', false),

(gen_random_uuid(), '65449044-2577-40db-a95d-ddc89424fc91', 'a', 'O uso de antiarrítmicos da classe I deve ser reservado para pacientes com arritmias ventriculares complexas sintomáticas e portadores de disfunção ventricular.', false),
(gen_random_uuid(), '65449044-2577-40db-a95d-ddc89424fc91', 'b', 'A presença de taquicardia ventricular não sustentada no Holter não tem implicação prognóstica, mas é indicativa de estudo eletrofisiológico.', false),
(gen_random_uuid(), '65449044-2577-40db-a95d-ddc89424fc91', 'c', 'A utilização de amiodarona está associada à maior mortalidade.', true),
(gen_random_uuid(), '65449044-2577-40db-a95d-ddc89424fc91', 'd', 'Indicação de ablação de taquicardia ventricular sustentada após primeiro episódio.', false),
(gen_random_uuid(), '65449044-2577-40db-a95d-ddc89424fc91', 'e', 'Indicação de marca-passo cardíaco devido a bloqueio bifascicular por maior risco de bloqueio avançado.', false),

(gen_random_uuid(), '1ea3ec65-e366-48e7-bb17-bb3bcc983905', 'a', 'Cintilografia com traçador ósseo → sequenciamento do gene da transtirretina → pesquisa de cadeia leve monoclonal.', false),
(gen_random_uuid(), '1ea3ec65-e366-48e7-bb17-bb3bcc983905', 'b', 'Pesquisa de cadeia leve monoclonal → cintilografia com traçador ósseo → sequenciamento do gene da transtirretina.', true),
(gen_random_uuid(), '1ea3ec65-e366-48e7-bb17-bb3bcc983905', 'c', 'Sequenciamento do gene da transtirretina → cintilografia com traçador ósseo → pesquisa de cadeia leve monoclonal.', false),
(gen_random_uuid(), '1ea3ec65-e366-48e7-bb17-bb3bcc983905', 'd', 'Pesquisa de cadeia leve monoclonal → sequenciamento do gene da transtirretina → cintilografia com traçador ósseo.', false),
(gen_random_uuid(), '1ea3ec65-e366-48e7-bb17-bb3bcc983905', 'e', 'Cintilografia com traçador ósseo → pesquisa de cadeia leve monoclonal → sequenciamento do gene da transtirretina.', false),

(gen_random_uuid(), 'dfe28064-419e-4a37-8e3c-2f260fcaf9ad', 'a', 'O ecocardiograma sob estresse com dobutamina está recomendado para a detecção da presença e do grau da obstrução da via de saída do ventrículo esquerdo.', false),
(gen_random_uuid(), 'dfe28064-419e-4a37-8e3c-2f260fcaf9ad', 'b', 'O movimento anterior sistólico da valva mitral deve ser investigado, porém raramente contribui para obstrução dinâmica na via de saída do ventrículo esquerdo.', false),
(gen_random_uuid(), 'dfe28064-419e-4a37-8e3c-2f260fcaf9ad', 'c', 'A maior espessura parietal do ventrículo esquerdo está associada a aumento da probabilidade de sintomas de insuficiência cardíaca progressiva.', false),
(gen_random_uuid(), 'dfe28064-419e-4a37-8e3c-2f260fcaf9ad', 'd', 'A disfunção diastólica está associada à gravidade da hipertrofia ventricular, sendo a causa provável da dispneia aos esforços em pacientes com doença não obstrutiva.', false),
(gen_random_uuid(), 'dfe28064-419e-4a37-8e3c-2f260fcaf9ad', 'e', 'A ressonância cardíaca permite a quantificação da fibrose miocárdica que é potencialmente relevante para estratificação de risco.', true),

(gen_random_uuid(), 'b5fffa7c-e31f-4081-b81a-8aacde39f791', 'a', 'Eletrocardiograma com alternância de onda T é um marcador de risco para morte súbita.', false),
(gen_random_uuid(), 'b5fffa7c-e31f-4081-b81a-8aacde39f791', 'b', 'A amiodarona constitui a terapêutica indicada para controlar arritmias ventriculares e prevenção de morte súbita.', false),
(gen_random_uuid(), 'b5fffa7c-e31f-4081-b81a-8aacde39f791', 'c', 'Maior espessura parietal do ventrículo esquerdo (VE) está associada a aumento da probabilidade de sintomas de insuficiência cardíaca progressiva.', false),
(gen_random_uuid(), 'b5fffa7c-e31f-4081-b81a-8aacde39f791', 'd', 'Os principais determinantes da insuficiência cardíaca progressiva são a obstrução da via de saída do ventrículo esquerdo (VE), a fibrilação atrial (FA) e a disfunção diastólica.', true),
(gen_random_uuid(), 'b5fffa7c-e31f-4081-b81a-8aacde39f791', 'e', 'Isquemia miocárdica secundária à disfunção microvascular é um importante componente fisiopatológico dessa patologia, mas não tem impacto no prognóstico.', false),

(gen_random_uuid(), '5eb43b26-32ce-4f4e-9ef0-5810d714630d', 'a', 'A hipótese mais provável é de doença arterial coronariana e o próximo passo é a realização de uma cintilografia miocárdica perfusional, em repouso e com estresse.', false),
(gen_random_uuid(), '5eb43b26-32ce-4f4e-9ef0-5810d714630d', 'b', 'Trata-se de uma miocardiopatia restritiva, provavelmente relacionada à endomiocardiofibrose.', false),
(gen_random_uuid(), '5eb43b26-32ce-4f4e-9ef0-5810d714630d', 'c', 'Deve-se dosar a ferritina sérica e o índice de saturação de transferrina; a ressonância abdominal, com a pesquisa da captação hepática de ferro auxilia no diagnóstico e o tratamento, provavelmente incluirá sangrias.', false),
(gen_random_uuid(), '5eb43b26-32ce-4f4e-9ef0-5810d714630d', 'd', 'A melhor estratégia diagnóstica consiste na solicitação da eletroforese de proteínas, imunofixação sanguínea e/ou urinária e cintilografia com pirofosfato.', true),
(gen_random_uuid(), '5eb43b26-32ce-4f4e-9ef0-5810d714630d', 'e', 'A biópsia endomiocárdica, com a coloração do vermelho Congo, mostra a patognomônica birefringência vermelha à luz polarizante e é imperativa.', false),

(gen_random_uuid(), '87ce8376-e72b-4d81-9379-2817ac5221d5', 'a', 'Serve para estratificação de risco visando a implante de cardiodesfibrilador implantável.', false),
(gen_random_uuid(), '87ce8376-e72b-4d81-9379-2817ac5221d5', 'b', 'É o método de mais baixo custo para se realizar o diagnóstico da cardiomiopatia hipertrófica.', false),
(gen_random_uuid(), '87ce8376-e72b-4d81-9379-2817ac5221d5', 'c', 'Pode ser utilizada para rastreamento de familiares de 1º grau de pacientes com diagnóstico confirmado.', true),
(gen_random_uuid(), '87ce8376-e72b-4d81-9379-2817ac5221d5', 'd', 'Permite avaliar os pacientes que responderão melhor ao betabloqueador.', false),
(gen_random_uuid(), '87ce8376-e72b-4d81-9379-2817ac5221d5', 'e', 'Deve ser usada de rotina em todos os pacientes.', false),

(gen_random_uuid(), '2509394a-5392-48c0-9737-34f1da790e6a', 'a', 'Em pacientes acima de 50 anos, a mortalidade continua sendo maior do que na população geral.', false),
(gen_random_uuid(), '2509394a-5392-48c0-9737-34f1da790e6a', 'b', 'Cardioversor desfibrilador implantável deve ser indicado para todos os pacientes.', false),
(gen_random_uuid(), '2509394a-5392-48c0-9737-34f1da790e6a', 'c', 'Fibrilação atrial é a arritmia sustentada mais comum.', true),
(gen_random_uuid(), '2509394a-5392-48c0-9737-34f1da790e6a', 'd', 'A alcoolização septal é o procedimento terapêutico com resultados mais duradouros.', false),
(gen_random_uuid(), '2509394a-5392-48c0-9737-34f1da790e6a', 'e', 'O marca-passo com dupla câmara reduz o gradiente intraventricular e tem resultados comparáveis à miomectomia cirúrgica.', false),

(gen_random_uuid(), '556c04a2-794a-41a5-add1-cac0ceccd2eb', 'a', 'Tanto na amiloidose por cadeia leve como na transtirretina, o achado de baixa voltagem é o mais frequente.', false),
(gen_random_uuid(), '556c04a2-794a-41a5-add1-cac0ceccd2eb', 'b', 'A presença de voltagem normal ou sinais de sobrecarga de ventrículo esquerdo excluem a possibilidade de amiloidose cardíaca.', false),
(gen_random_uuid(), '556c04a2-794a-41a5-add1-cac0ceccd2eb', 'c', 'Ausência de progressão de ondas R em derivações precordiais e desproporção da voltagem em relação à espessura miocárdica são achados sugestivos de amiloidose cardíaca, independentemente do tipo de amiloidose.', true),
(gen_random_uuid(), '556c04a2-794a-41a5-add1-cac0ceccd2eb', 'd', 'Fibrilação atrial torna pouco provável o diagnóstico de amiloidose cardíaca, mesmo na presença de baixa voltagem.', false),
(gen_random_uuid(), '556c04a2-794a-41a5-add1-cac0ceccd2eb', 'e', 'Bloqueio atrioventricular de primeiro grau é achado pouco comum na amiloidose cardíaca.', false),

(gen_random_uuid(), '3c608c00-3fda-4b76-ba2b-ee2f0d5cd2a6', 'a', 'A doença se manifesta ainda na infância. Logo, todos os parentes acima de 5 anos devem ser rastreados com eletrocardiograma e ecocardiograma. A enfermidade está descartada naqueles que já tiveram os exames normais ainda na idade escolar.', false),
(gen_random_uuid(), '3c608c00-3fda-4b76-ba2b-ee2f0d5cd2a6', 'b', 'Os betabloqueadores e os inibidores dos canais de cálcio são contraindicados nessa doença, uma vez que têm efeito inotrópico negativo e podem piorar os sintomas.', false),
(gen_random_uuid(), '3c608c00-3fda-4b76-ba2b-ee2f0d5cd2a6', 'c', 'O paciente deve ser submetido à miectomia para redução do gradiente intraventricular e melhora da sobrevida.', false),
(gen_random_uuid(), '3c608c00-3fda-4b76-ba2b-ee2f0d5cd2a6', 'd', 'A fibrilação atrial é uma arritmia frequente nessa doença. A droga de escolha para controle do ritmo nesses pacientes é a propafenona.', false),
(gen_random_uuid(), '3c608c00-3fda-4b76-ba2b-ee2f0d5cd2a6', 'e', 'Está indicado o implante de cardiodesfibrilador (CDI).', true),

(gen_random_uuid(), '1f7d3184-0ab2-4ecf-92f9-586cb8d4df47', 'a', 'Eletrocardiograma em paciente com Doença de Chagas assintomático e com exame físico normal.', false),
(gen_random_uuid(), '1f7d3184-0ab2-4ecf-92f9-586cb8d4df47', 'b', 'Ecocardiograma em paciente com Doença de Chagas sintomático e com eletrocardiograma (ECG) alterado.', false),
(gen_random_uuid(), '1f7d3184-0ab2-4ecf-92f9-586cb8d4df47', 'c', 'Coronariografia em paciente com Doença de Chagas com precordialgia e bloqueio completo do ramo direito associado a hemibloqueio anterossuperior esquerdo.', true),
(gen_random_uuid(), '1f7d3184-0ab2-4ecf-92f9-586cb8d4df47', 'd', 'Holter em paciente com Doença de Chagas assintomático, com eletrocardiograma (ECG) normal e ecocardiograma evidenciando fração de ejeção de 35% e com hipocinesia inferolateral.', false),
(gen_random_uuid(), '1f7d3184-0ab2-4ecf-92f9-586cb8d4df47', 'e', 'Estudo eletrofisiológico em paciente com Doença de Chagas ressuscitado após parada cardíaca e com fração de ejeção de 30%.', false),

(gen_random_uuid(), '7e6b6cdb-f960-43d2-9536-3591febb4346', 'a', 'Espessamento do septo interventricular associado a baixas voltagens no ECG.', false),
(gen_random_uuid(), '7e6b6cdb-f960-43d2-9536-3591febb4346', 'b', 'Discreto derrame pericárdico.', false),
(gen_random_uuid(), '7e6b6cdb-f960-43d2-9536-3591febb4346', 'c', 'O ecocardiograma com strain (Speckle-Tracking - análise da deformação longitudinal) mostra o padrão clássico de hipocinesia apical.', true),
(gen_random_uuid(), '7e6b6cdb-f960-43d2-9536-3591febb4346', 'd', 'Espessamento da parede livre do ventrículo direito.', false),
(gen_random_uuid(), '7e6b6cdb-f960-43d2-9536-3591febb4346', 'e', 'Espessamento valvar difuso.', false),

(gen_random_uuid(), 'b3ac8814-1e7d-4c11-9d54-ad4cbdf7569a', 'a', 'Presença de um VO2 máximo < 30mL/Kg/min.', false),
(gen_random_uuid(), 'b3ac8814-1e7d-4c11-9d54-ad4cbdf7569a', 'b', 'Arritmias ventriculares frequentes e sustentadas.', false),
(gen_random_uuid(), 'b3ac8814-1e7d-4c11-9d54-ad4cbdf7569a', 'c', 'Espessura da parede do ventrículo esquerdo > 20mm.', false),
(gen_random_uuid(), 'b3ac8814-1e7d-4c11-9d54-ad4cbdf7569a', 'd', 'Aumento do tamanho da cavidade ventricular esquerda excedendo 55mm.', true),
(gen_random_uuid(), 'b3ac8814-1e7d-4c11-9d54-ad4cbdf7569a', 'e', 'O grau de espessamento em uma ou mais regiões da parede do ventrículo esquerdo ser maior do que em outras áreas.', false),

(gen_random_uuid(), 'b3883a90-8370-4915-bb9d-a4ca7602d2f7', 'a', 'A principal suspeita é de miocardiopatia hipertrófica, principal causa de morte súbita de atletas jovens.', true),
(gen_random_uuid(), 'b3883a90-8370-4915-bb9d-a4ca7602d2f7', 'b', 'A principal suspeita é de cardiomiopatia hipertensiva; ressonância magnética está indicada.', false),
(gen_random_uuid(), 'b3883a90-8370-4915-bb9d-a4ca7602d2f7', 'c', 'A principal suspeita é de miocardiopatia hipertrófica; tem indicação de alcoolização septal, pois está sintomático ao esforço.', false),
(gen_random_uuid(), 'b3883a90-8370-4915-bb9d-a4ca7602d2f7', 'd', 'A principal suspeita é de amiloidose; estudo de ressonância magnética cardíaca está indicado.', false),
(gen_random_uuid(), 'b3883a90-8370-4915-bb9d-a4ca7602d2f7', 'e', 'A principal suspeita é de miocardiopatia hipertrófica; nesta condição, a utilidade da análise genética ainda não foi definida.', false),

(gen_random_uuid(), 'f8a325f5-3524-4978-b12b-137475a4baea', 'a', 'Tem padrão de herança autossômica recessiva.', true),
(gen_random_uuid(), 'f8a325f5-3524-4978-b12b-137475a4baea', 'b', 'Cerca de 30% dos pacientes apresentam a forma não obstrutiva.', false),
(gen_random_uuid(), 'f8a325f5-3524-4978-b12b-137475a4baea', 'c', 'O gradiente subaórtico e o sopro sistólico de ejeção costumam ser dinâmicos.', false),
(gen_random_uuid(), 'f8a325f5-3524-4978-b12b-137475a4baea', 'd', 'É comum que a hipertrofia do ventrículo esquerdo se desenvolva dinamicamente após um período variável de latência.', false),
(gen_random_uuid(), 'f8a325f5-3524-4978-b12b-137475a4baea', 'e', 'Os miócitos mostram aumento do diâmetro transversal e formas bizarras, mantendo frequentemente conexões intercelulares com muitas células adjacentes.', false),

(gen_random_uuid(), 'aeaa7d53-1ec3-421a-9165-629f0523613b', 'a', 'O teste ergométrico é útil para a estratificação de risco de morte súbita destes pacientes. Quando a elevação da pressão sistólica no esforço é ≤ 20 mmHg ou ocorre a queda > 20 mmHg, há menor risco de morte súbita.', false),
(gen_random_uuid(), 'aeaa7d53-1ec3-421a-9165-629f0523613b', 'b', 'O ecocardiograma diagnostica a doença, e os achados de gradientes de via de saída do VE ≤ 30 mmHg caracterizam a forma obstrutiva em repouso.', false),
(gen_random_uuid(), 'aeaa7d53-1ec3-421a-9165-629f0523613b', 'c', 'Situações que diminuam a pré-carga, como ficar em pé e realizar a manobra de Valsalva, reduzem o volume cavitário do ventrículo esquerdo (VE), aumentando o gradiente e o sopro, que é melhor audível ao longo da borda esternal esquerda baixa e não apresenta irradiação carotídea.', true),
(gen_random_uuid(), 'aeaa7d53-1ec3-421a-9165-629f0523613b', 'd', 'A ressonância magnética permite avaliar melhor a distribuição da hipertrofia e afastar outras etiologias, como amiloidose e doença de Fabry; além disso, avalia o padrão de fibrose miocárdica (pela técnica de realce precoce), graças à distribuição intracelular do gadolínio.', false),
(gen_random_uuid(), 'aeaa7d53-1ec3-421a-9165-629f0523613b', 'e', 'O verapamil melhora os sintomas e a capacidade para o exercício, em especial diante da obstrução na via de saída do ventrículo esquerdo (VE). Os betabloqueadores são amplamente usados para reduzir o gradiente desencadeado pelo exercício. Diuréticos administrados com cuidado podem beneficiar predominantemente pacientes com a forma obstrutiva.', false),

(gen_random_uuid(), '34df4198-c6d9-40e6-8028-0f03c50fb3dc', 'a', 'A ressonância magnética do coração é especialmente útil na avaliação de pacientes com diagnóstico de miocardite fulminante com instabilidade hemodinâmica.', true),
(gen_random_uuid(), '34df4198-c6d9-40e6-8028-0f03c50fb3dc', 'b', 'A realização da biópsia endomiocárdica do ventrículo esquerdo deve ser realizada somente nos casos em que o processo esteja definitivamente limitado a esta cavidade, o que pode ser definido, em alguns casos, pelo exame de ressonância magnética do coração.', false),
(gen_random_uuid(), '34df4198-c6d9-40e6-8028-0f03c50fb3dc', 'c', 'A cintilografia com 67-gálio, pela elevada sensibilidade durante o diagnóstico de miocardite, deve ser realizada naqueles pacientes com quadro clínico sugestivo com mais de 3 meses de evolução.', false),
(gen_random_uuid(), '34df4198-c6d9-40e6-8028-0f03c50fb3dc', 'd', 'A exemplo do que ocorre nas síndromes coronarianas agudas, geralmente existe uma curva de elevação e redução habitual e gradual dos marcadores de necrose miocárdica na miocardite.', false),
(gen_random_uuid(), '34df4198-c6d9-40e6-8028-0f03c50fb3dc', 'e', 'O eletrocardiograma não deve ser realizado rotineiramente, pois, na fase aguda, predominam os sinais de sobrecarga ventricular esquerda e bloqueio de ramo esquerdo, sem valor prognóstico nesta fase.', false),

(gen_random_uuid(), '23098886-907f-4bcb-96a3-1e5927f34f8e', 'a', 'dilatada', false),
(gen_random_uuid(), '23098886-907f-4bcb-96a3-1e5927f34f8e', 'b', 'restritiva', false),
(gen_random_uuid(), '23098886-907f-4bcb-96a3-1e5927f34f8e', 'c', 'isquêmica', true),
(gen_random_uuid(), '23098886-907f-4bcb-96a3-1e5927f34f8e', 'd', 'hipertrófica', false),
(gen_random_uuid(), '23098886-907f-4bcb-96a3-1e5927f34f8e', 'e', 'arritmogênica do ventrículo direito', false),

(gen_random_uuid(), '1815986a-9f76-43a5-a083-c87577b5d065', 'a', 'O prognóstico na hemocromatose depende da precocidade de seu diagnóstico, pois, uma vez iniciado o tratamento com sangrias terapêuticas, pode haver melhora da disfunção cardíaca, com consequente redução da morbidade e mortalidade.', true),
(gen_random_uuid(), '1815986a-9f76-43a5-a083-c87577b5d065', 'b', 'Na forma familiar da amiloidose, também conhecida como de cadeia leve (AL), ocorre miocardiopatia associada à polineuropatia e neuropatia autonômica, que costumam preceder o quadro cardíaco. Embora a proteína mutante seja produzida no fígado, não há espaço para transplante hepático.', false),
(gen_random_uuid(), '1815986a-9f76-43a5-a083-c87577b5d065', 'c', 'A sarcoidose cardíaca caracteriza-se histopatologicamente pela presença de granulomas caseosos. Pode ocorrer insuficiência cardíaca, dor torácica e arritmias ventriculares, mas não ocorrem distúrbios de condução.', false),
(gen_random_uuid(), '1815986a-9f76-43a5-a083-c87577b5d065', 'd', 'A endomiocardiofibrose caracteriza-se por comprometimento fibrótico endocárdico e do miocárdio adjacente, poupando, contudo, os ápices ventriculares. Quando acomete o ventrículo esquerdo (VE), deve ser diferenciada da pericardite constritiva.', false),
(gen_random_uuid(), '1815986a-9f76-43a5-a083-c87577b5d065', 'e', 'O diagnóstico de miocardiopatia restritiva deve ser lembrado em pacientes com insuficiência cardíaca, cardiomegalia à radiografia de tórax, átrios pequenos ao ecocardiograma e calcificação pericárdica.', false),

(gen_random_uuid(), 'dabd86f3-10f6-4cf8-b0b7-df2726ffec42', 'a', 'Disfunção ventricular esquerda segmentar, predominantemente da parede inferior.', false),
(gen_random_uuid(), 'dabd86f3-10f6-4cf8-b0b7-df2726ffec42', 'b', 'Ocorrência de dor torácica, supradesnivelamento do segmento ST e inversão da onda T ao eletrocardiograma, sendo sempre necessário o diagnóstico diferencial com síndrome coronariana aguda.', true),
(gen_random_uuid(), 'dabd86f3-10f6-4cf8-b0b7-df2726ffec42', 'c', 'Doença arterial coronária obstrutiva, com frequente ruptura de placa e formação de trombo.', false),
(gen_random_uuid(), 'dabd86f3-10f6-4cf8-b0b7-df2726ffec42', 'd', 'Sexo masculino, ocorrendo com frequência em faixas etárias abaixo dos 50 anos, na vigência de estresse emocional.', false),
(gen_random_uuid(), 'dabd86f3-10f6-4cf8-b0b7-df2726ffec42', 'e', 'Ausência de elevação dos marcadores de necrose miocárdica e elevação dos peptídeos natriuréticos BNP e NT-proBNP.', false),

(gen_random_uuid(), 'e9b0a3f2-008f-487a-9ada-e62519fbe04c', 'a', 'A biópsia endomiocárdica tem baixa taxa de resultados falso-negativos.', false),
(gen_random_uuid(), 'e9b0a3f2-008f-487a-9ada-e62519fbe04c', 'b', 'A progressão para a insuficiência cardíaca ocorre na maioria dos pacientes.', false),
(gen_random_uuid(), 'e9b0a3f2-008f-487a-9ada-e62519fbe04c', 'c', 'Os pacientes costumam apresentar a doença entre a adolescência e os 40 anos de idade.', true),
(gen_random_uuid(), 'e9b0a3f2-008f-487a-9ada-e62519fbe04c', 'd', 'Uma minoria dos pacientes que sofrem morte súbita cardíaca apresenta um histórico de síncope, o que faz desta um evento prognóstico importante.', false),
(gen_random_uuid(), 'e9b0a3f2-008f-487a-9ada-e62519fbe04c', 'e', 'É característico que o coração afetado com CAVD apresente uma substituição gordurosa ou fibrogordurosa do miocárdio, em especial no ventrículo esquerdo.', false),

(gen_random_uuid(), '8a62c8f7-92b4-423e-ba75-3588a702402d', 'a', 'Há indicação de cardiodesfibrilador implantável para prevenção da morte súbita cardíaca, frequente nesses pacientes.', true),
(gen_random_uuid(), '8a62c8f7-92b4-423e-ba75-3588a702402d', 'b', 'A prescrição de inibidores da enzima conversora da angiotensina (iECA) ou bloqueadores de receptores da angiotensina (BRA) mudam a evolução clínica e o prognóstico da doença.', false),
(gen_random_uuid(), '8a62c8f7-92b4-423e-ba75-3588a702402d', 'c', 'Os betabloqueadores são contraindicados, em função dos bloqueios atrioventriculares que comumente ocorrem nos portadores dessa forma de cardiomiopatia.', false),
(gen_random_uuid(), '8a62c8f7-92b4-423e-ba75-3588a702402d', 'd', 'Diuréticos de alça e antagonistas da aldosterona não são utilizados, pois podem precipitar episódios de taquicardia ventricular.', false),
(gen_random_uuid(), '8a62c8f7-92b4-423e-ba75-3588a702402d', 'e', 'O padrão de herança autossômico recessiva é a forma mais comum desta doença.', false),

(gen_random_uuid(), '1c2a9742-6b75-431d-877b-b7371efe8e1d', 'a', 'A paciente tem alta suspeita clínica de amiloidose cardíaca e deve ser submetida à eletroforese de proteínas plasmáticas, além de imunofixação de proteínas plasmáticas e urinárias para detecção de cadeias leves. Deve também ser submetida à ressonância magnética de coração para pesquisa de realce tardio subendocárdico.', true),
(gen_random_uuid(), '1c2a9742-6b75-431d-877b-b7371efe8e1d', 'b', 'O diagnóstico mais provável é de miocardiopatia hipertrófica, já que o septo interventricular e a parede posterior do ventrículo esquerdo têm espessura aumentada.', false),
(gen_random_uuid(), '1c2a9742-6b75-431d-877b-b7371efe8e1d', 'c', 'A possibilidade mais provável é de que a paciente tenha endomiocardiofibrose, por causa do aumento de volume do átrio esquerdo e da disfunção diastólica importante.', false),
(gen_random_uuid(), '1c2a9742-6b75-431d-877b-b7371efe8e1d', 'd', 'A cintilografia óssea com pirofosfato de tecnécio está indicada por ser patognomônica de amiloidose de cadeias leves.', false),
(gen_random_uuid(), '1c2a9742-6b75-431d-877b-b7371efe8e1d', 'e', 'A suspeita clínica de endomiocardiofibrose fica reforçada pelos sinais de congestão venosa sistêmica e pela ausculta cardíaca normal, já que o comprometimento é de via de saída dos ventrículos.', false),

(gen_random_uuid(), '5a3ec403-a095-45fd-bdb5-0a85d5d8db95', 'a', 'Endomiocardiofibrose.', false),
(gen_random_uuid(), '5a3ec403-a095-45fd-bdb5-0a85d5d8db95', 'b', 'Cardiomiopatia hipertrófica.', false),
(gen_random_uuid(), '5a3ec403-a095-45fd-bdb5-0a85d5d8db95', 'c', 'Miocárdio não compactado.', true),
(gen_random_uuid(), '5a3ec403-a095-45fd-bdb5-0a85d5d8db95', 'd', 'Cardiomiopatia dilatada.', false),
(gen_random_uuid(), '5a3ec403-a095-45fd-bdb5-0a85d5d8db95', 'e', 'Cardiomiopatia chagásica.', false),

(gen_random_uuid(), 'e9e58b71-55e1-432e-bd6d-cf4b8bd6216d', 'a', 'Na amiloidose m-TTR, o tratamento quimioterápico se impõe e objetiva combater os clones de células B medulares, os quais produzem as cadeias pesadas de imunoglobulinas que se depositam nos tecidos.', false),
(gen_random_uuid(), 'e9e58b71-55e1-432e-bd6d-cf4b8bd6216d', 'b', 'A doença de Fabry, relacionada à deficiência de betagalactosidase, é associada à herança autossômica dominante e se caracteriza por graus acentuados de hipertrofia ventricular desde a adolescência, levando à dispneia precoce e à angina relacionada à doença coronariana epicárdica.', false),
(gen_random_uuid(), 'e9e58b71-55e1-432e-bd6d-cf4b8bd6216d', 'c', 'A amiloidose cardíaca deve ser considerada no diagnóstico diferencial nos pacientes com insuficiência cardíaca e fração de ejeção preservada.', true),
(gen_random_uuid(), 'e9e58b71-55e1-432e-bd6d-cf4b8bd6216d', 'd', 'A hemocromatose primária ocorre devido ao depósito de ferro em vários órgãos, relacionada à herança genética autossômica dominante, sendo decorrente da eliminação reduzida do ferro absorvido e havendo infiltração do coração precoce quando comparada aos outros órgãos sólidos, como fígado e pâncreas.', false),
(gen_random_uuid(), 'e9e58b71-55e1-432e-bd6d-cf4b8bd6216d', 'e', 'As imagens de PET (tomografia por emissão de pósitrons) têm pouca utilidade para o diagnóstico e seguimento em pacientes portadores de sarcoidose cardíaca, dada a ausência de inflamação perigranulomatosa significativa nessa patologia.', false),

(gen_random_uuid(), '48cd5330-df7e-45b0-9794-08d96d9ffb1f', 'a', 'Miocardiopatia isquêmica, função do ventrículo esquerdo preservada, regurgitação mitral primária.', false),
(gen_random_uuid(), '48cd5330-df7e-45b0-9794-08d96d9ffb1f', 'b', 'Miocardiopatia hipertrófica, função do ventrículo esquerdo preservada, regurgitação mitral primária.', false),
(gen_random_uuid(), '48cd5330-df7e-45b0-9794-08d96d9ffb1f', 'c', 'Miocardiopatia dilatada com grave disfunção ventricular esquerda e regurgitação mitral secundária.', true),
(gen_random_uuid(), '48cd5330-df7e-45b0-9794-08d96d9ffb1f', 'd', 'Miocardiopatia dilatada com grave disfunção ventricular e regurgitação mitral primária.', false),
(gen_random_uuid(), '48cd5330-df7e-45b0-9794-08d96d9ffb1f', 'e', 'Miocardiopatia hipertrófica com grave disfunção ventricular e regurgitação mitral primária.', false),

(gen_random_uuid(), '00c3f96e-1454-447e-80bd-816ae101a106', 'a', 'A principal hipótese diagnóstica neste caso é a sarcoidose. A presença de granulomas hepáticos e/ou pulmonares, vistos à tomografia computadorizada e/ou ressonância nuclear magnética abdominal e torácica, bem como os achados de espessamento da parede miocárdica com alterações da contratilidade, edema e realce tardio à ressonância nuclear magnética cardíaca, reforçam a hipótese. O tratamento baseia-se no uso de corticosteroides e imunossupressores.', true),
(gen_random_uuid(), '00c3f96e-1454-447e-80bd-816ae101a106', 'b', 'O quadro do paciente sugere miocardite viral, provavelmente por citomegalovírus ou síndrome da mononucleose infecciosa. Deve-se realizar biópsia endomiocárdica, definir o vírus responsável e iniciar antivirais.', false),
(gen_random_uuid(), '00c3f96e-1454-447e-80bd-816ae101a106', 'c', 'O quadro provável é da forma aguda da miocardiopatia chagásica. A presença de realce tardio transmural à ressonância cardíaca favorece a hipótese. Por ainda estar em uma fase precoce, o uso do benzonidazol está indicado.', false),
(gen_random_uuid(), '00c3f96e-1454-447e-80bd-816ae101a106', 'd', 'A hipótese principal é de endocardite infecciosa. Importante solicitar ecocardiograma transesofágico e hemoculturas, iniciar ampicilina e gentamicina até definição do antibiograma.', false),
(gen_random_uuid(), '00c3f96e-1454-447e-80bd-816ae101a106', 'e', 'O diagnóstico mais provável é amiloidose. Nesse quadro, os granulomas ocorrem devido ao depósito de amiloide A (AA).', false),

(gen_random_uuid(), '697a832c-fd2c-4e28-8b88-446388b37bf6', 'a', 'A sarcoidose pode afetar átrios, ventrículos, valvas, músculos papilares e sistema de condução.', false),
(gen_random_uuid(), '697a832c-fd2c-4e28-8b88-446388b37bf6', 'b', 'Alterações contráteis segmentares com distribuição não coronariana, afilamento anterobasal do septo com ecogenicidade aumentada ao ecocardiograma transtorácico são muito sugestivos.', false),
(gen_random_uuid(), '697a832c-fd2c-4e28-8b88-446388b37bf6', 'c', 'Imagens híbridas de tomografia por emissão de pósitrons e ressonância magnética (PET-RM) possibilitam avaliar simultaneamente a estrutura e função cardíaca, detectar fibrose e determinar o grau de inflamação ativa; atualmente, é o método diagnóstico de escolha.', false),
(gen_random_uuid(), '697a832c-fd2c-4e28-8b88-446388b37bf6', 'd', 'A forma cardíaca clinicamente evidente ocorre em 25% dos pacientes com sarcoidose sistêmica; já o acometimento pulmonar é raro, caracterizado por linfadenopatia hilar bilateral, opacidades reticulares parenquimatosas e, em casos avançados, sinais de doença intersticial pulmonar e fibrose.', true),
(gen_random_uuid(), '697a832c-fd2c-4e28-8b88-446388b37bf6', 'e', 'A terapêutica inclui imunossupressão para as lesões ativas, tratamento da insuficiência cardíaca e terapia antiarrítmica.', false),

(gen_random_uuid(), 'ea15017b-edc4-4495-9b90-a9e399d5bf32', 'a', 'Diante de um quadro clínico sugestivo de miocardite aguda, deve-se proceder à investigação complementar que envolva exames laboratoriais, ecocardiograma, seguida da indispensável biópsia miocárdica, a qual, em última análise, permitirá a escolha do tratamento mais efetivo contra o agente etiológico identificado.', false),
(gen_random_uuid(), 'ea15017b-edc4-4495-9b90-a9e399d5bf32', 'b', 'A miocardite de células gigantes raramente apresenta um curso fulminante e responde bem ao tratamento convencional, apresentando melhor prognóstico do que a causada por infecções virais.', false),
(gen_random_uuid(), 'ea15017b-edc4-4495-9b90-a9e399d5bf32', 'c', 'Na Doença de Chagas, a manifestação da miocardite aguda independe do grau de infecção sistêmica, pois o quadro clínico é quase sempre frustro, exigindo, portanto, alto grau de suspeição clínica.', false),
(gen_random_uuid(), 'ea15017b-edc4-4495-9b90-a9e399d5bf32', 'd', 'Nas formas agudas com dor torácica, pode se manifestar de modo similar à dor anginosa, com achados semelhantes aos de uma síndrome coronariana aguda, incluindo alterações no eletrocardiograma (ECG) e elevação dos marcadores de necrose miocárdica.', true),
(gen_random_uuid(), 'ea15017b-edc4-4495-9b90-a9e399d5bf32', 'e', 'Atletas com diagnóstico de miocardite têm baixa incidência de morte súbita, podendo retornar ao treinamento após 4 a 6 semanas de repouso, desde que comprovada a ausência de disfunção ventricular ou arritmias ventriculares.', false),

(gen_random_uuid(), '940d4a45-d8ce-4fa3-a6ad-e9a34306547e', 'a', 'O peptídeo natriurético cerebral (NT-pro-BNP) encontra-se elevado nos casos de miocardiopatia dilatada secundária à miocardite e permanece elevado mesmo após a recuperação da função ventricular esquerda.', false),
(gen_random_uuid(), '940d4a45-d8ce-4fa3-a6ad-e9a34306547e', 'b', 'Níveis elevados de troponinas cardíacas I e T (cTnI e cTnT) estão associados à gravidade da miocardite e ao prognóstico.', true),
(gen_random_uuid(), '940d4a45-d8ce-4fa3-a6ad-e9a34306547e', 'c', 'Os títulos de anticorpos virais circulantes correlacionam com os genomas virais de tecidos e podem ser usados para o diagnóstico na prática clínica.', false),
(gen_random_uuid(), '940d4a45-d8ce-4fa3-a6ad-e9a34306547e', 'd', 'O aumento da duração do QRS maior que 120 milissegundos e presença de ondas Q são achados inespecíficos ao eletrocardiograma, sem valor prognóstico.', false),
(gen_random_uuid(), '940d4a45-d8ce-4fa3-a6ad-e9a34306547e', 'e', 'Nos casos suspeitos de miocardite, a sensibilidade e a especificidade da ressonância cardíaca para detectar realce tardio são maiores após duas semanas do início dos sintomas.', false),

(gen_random_uuid(), 'a39c1193-735b-45da-b7bf-ea4972c55349', 'a', 'A normalização da função ventricular esquerda, a motilidade da parede ventricular e as dimensões cardíacas são critérios necessários para o retorno às atividades esportivas com base no ecocardiograma em repouso.', false),
(gen_random_uuid(), 'a39c1193-735b-45da-b7bf-ea4972c55349', 'b', 'Extrassístoles ventriculares frequentes não contraindicam o retorno às atividades esportivas.', false),
(gen_random_uuid(), 'a39c1193-735b-45da-b7bf-ea4972c55349', 'c', 'A realização de biópsia miocárdica é fundamental no atleta de alto rendimento para definir o tratamento e prognóstico no retorno às atividades esportivas.', false),
(gen_random_uuid(), 'a39c1193-735b-45da-b7bf-ea4972c55349', 'd', 'Marcadores inflamatórios não interferem na liberação do atleta para retorno às atividades competitivas.', false),
(gen_random_uuid(), 'a39c1193-735b-45da-b7bf-ea4972c55349', 'e', 'A morte súbita pode ocorrer em sua fase aguda, quando o indivíduo diagnosticado com miocardite não se absteve de atividades esportivas por um período de recuperação de seis meses.', true),

(gen_random_uuid(), '1c958654-809b-4e84-886b-47fb0f4a7ed5', 'a', 'Miocardite de células gigantes e eosinofílica são potenciais causas de miocardite fulminante, e o fator causal da miocardite pode ser definido por meio de ressonância nuclear magnética.', false),
(gen_random_uuid(), '1c958654-809b-4e84-886b-47fb0f4a7ed5', 'b', 'A biópsia endomiocárdica em geral não está indicada em caso de miocardite fulminante.', false),
(gen_random_uuid(), '1c958654-809b-4e84-886b-47fb0f4a7ed5', 'c', 'O suporte mecânico circulatório deve ser considerado para pacientes com miocardite fulminante como ponte para transplante ou para recuperação.', true),
(gen_random_uuid(), '1c958654-809b-4e84-886b-47fb0f4a7ed5', 'd', 'A sobrevida após transplante cardíaco para pacientes com miocardite é pior do que para outras etiologias.', false),
(gen_random_uuid(), '1c958654-809b-4e84-886b-47fb0f4a7ed5', 'e', 'O tratamento com imunossupressores não está indicado na miocardite de células gigantes.', false),

(gen_random_uuid(), '347ae61c-4c4f-42da-9ec8-6b37c7c1450c', 'a', 'É uma forma transitória de cardiomiopatia que ocorre habitualmente após um grande estresse e normalmente leva à discinesia e ao "balonismo" do ápice ventricular.', false),
(gen_random_uuid(), '347ae61c-4c4f-42da-9ec8-6b37c7c1450c', 'b', 'Frequentemente mimetiza síndrome coronariana aguda, com dor torácica, supradesnivelamento do segmento ST anterior e troponina elevada.', false),
(gen_random_uuid(), '347ae61c-4c4f-42da-9ec8-6b37c7c1450c', 'c', 'A hiperativação simpática ocasiona o fenômeno observado na Takotsubo de aumento regional da contratilidade miocárdica associada à depressão da contratilidade com balonamento.', false),
(gen_random_uuid(), '347ae61c-4c4f-42da-9ec8-6b37c7c1450c', 'd', 'A presença de estresse físico ou emocional como gatilho enfatiza o papel da atividade simpática com principal fator para o desenvolvimento de Takotsubo.', false),
(gen_random_uuid(), '347ae61c-4c4f-42da-9ec8-6b37c7c1450c', 'e', 'A ausência de um gatilho, como estresse físico ou emocional, exclui a síndrome.', true),

(gen_random_uuid(), '7eb4e3c6-f489-42a4-a29a-bc0bd04d069a', 'a', 'Uma causa importante é a miocardite, sendo os fungos os agentes infecciosos mais frequentes.', false),
(gen_random_uuid(), '7eb4e3c6-f489-42a4-a29a-bc0bd04d069a', 'b', 'Estima-se que a maioria dos casos se deva ao abuso de etanol, cujo consumo causa aumento da frequência cardíaca e vasodilatação, levando a prejuízo da microcirculação miocárdica, à diminuição da contratilidade e ao aumento da pressão diastólica final do ventrículo esquerdo.', false),
(gen_random_uuid(), '7eb4e3c6-f489-42a4-a29a-bc0bd04d069a', 'c', 'Agentes quimioterápicos como as antraciclinas lesam o miocárdio por meio de estresse oxidativo secundário às alterações da função mitocondrial e fosforilação oxidativa, porém levam à cardiomiopatia hipertrófica e não à CMD.', false),
(gen_random_uuid(), '7eb4e3c6-f489-42a4-a29a-bc0bd04d069a', 'd', 'A cardiomiopatia periparto é um tipo muito frequente de CMD, que ocorre usualmente nos dois primeiros trimestres de gestação; raramente ocorre no terceiro trimestre e/ou nos primeiros 5 meses de puerpério.', false),
(gen_random_uuid(), '7eb4e3c6-f489-42a4-a29a-bc0bd04d069a', 'e', 'As mutações genéticas são responsáveis por cerca de 35% dos casos e envolvem genes que codificam proteínas do sarcômero, do citoesqueleto, dos desmossomos e da membrana nuclear.', true),

(gen_random_uuid(), 'b6140576-d7b0-447b-8f94-6238282c45bf', 'a', 'A fibrose na região apical acomete os músculos papilares.', false),
(gen_random_uuid(), 'b6140576-d7b0-447b-8f94-6238282c45bf', 'b', 'É uma doença insidiosa, acometendo os pacientes mais idosos em regiões tropicais.', false),
(gen_random_uuid(), 'b6140576-d7b0-447b-8f94-6238282c45bf', 'c', 'Na fase sintomática, a sobrevida aproximada é de 50% em dois anos.', true),
(gen_random_uuid(), 'b6140576-d7b0-447b-8f94-6238282c45bf', 'd', 'Na patogênese da doença estão envolvidos apenas fatores individuais e suscetibilidade.', false),
(gen_random_uuid(), 'b6140576-d7b0-447b-8f94-6238282c45bf', 'e', 'O transplante cardíaco é uma das formas de tratamento; entretanto, os resultados não são animadores.', false),

(gen_random_uuid(), 'ed11d80a-ea7d-4c79-a84c-0c4319e433de', 'a', 'É mais comum em mulheres de meia idade.', false),
(gen_random_uuid(), 'ed11d80a-ea7d-4c79-a84c-0c4319e433de', 'b', 'A coronariografia mostra doença aterosclerótica associada.', true),
(gen_random_uuid(), 'ed11d80a-ea7d-4c79-a84c-0c4319e433de', 'c', 'O eletrocardiograma pode simular um infarto agudo do miocárdio.', false),
(gen_random_uuid(), 'ed11d80a-ea7d-4c79-a84c-0c4319e433de', 'd', 'O ecocardiograma mostra disfunção ventricular regional, sendo a forma apical uma das apresentações encontradas.', false),
(gen_random_uuid(), 'ed11d80a-ea7d-4c79-a84c-0c4319e433de', 'e', 'A ressonância cardíaca mostra presença de miocárdio viável em áreas acinéticas vista na ecocardiografia ou na ventriculografia.', false),

(gen_random_uuid(), 'da12f85c-ea03-4882-8f4c-c76ba17bf6a6', 'a', 'Radiografia de tórax.', false),
(gen_random_uuid(), 'da12f85c-ea03-4882-8f4c-c76ba17bf6a6', 'b', 'Ecocardiograma transtorácico.', true),
(gen_random_uuid(), 'da12f85c-ea03-4882-8f4c-c76ba17bf6a6', 'c', 'Ressonância magnética cardíaca.', false),
(gen_random_uuid(), 'da12f85c-ea03-4882-8f4c-c76ba17bf6a6', 'd', 'Tomografia computadorizada do tórax.', false),
(gen_random_uuid(), 'da12f85c-ea03-4882-8f4c-c76ba17bf6a6', 'e', 'Pulso arterial alternante é característico de casos graves.', false),

(gen_random_uuid(), '9551914e-0384-4e28-98a5-06eb87ac7b37', 'a', 'Endomiocardiofibrose, cardiomiopatia hipertrófica apical e trombos apicais.', true),
(gen_random_uuid(), '9551914e-0384-4e28-98a5-06eb87ac7b37', 'b', 'Endomiocardiofibrose, cardiomiopatia hipertrófica apical e amiloidose.', false),
(gen_random_uuid(), '9551914e-0384-4e28-98a5-06eb87ac7b37', 'c', 'Endomiocardiofibrose e cardiomiopatia hipertrófica obstrutiva.', false),
(gen_random_uuid(), '9551914e-0384-4e28-98a5-06eb87ac7b37', 'd', 'Endomiocardiofibrose e sarcoidose.', false),
(gen_random_uuid(), '9551914e-0384-4e28-98a5-06eb87ac7b37', 'e', 'Endomiocardiofibrose e cardiomiopatia de Takotsubo.', false),

(gen_random_uuid(), '8baddc7e-b426-40d5-8f7f-00ba834e7912', 'a', 'As mulheres jovens em geral apresentam formas mais graves, especialmente insuficiência cardíaca.', true),
(gen_random_uuid(), '8baddc7e-b426-40d5-8f7f-00ba834e7912', 'b', 'O envolvimento cardíaco produz um padrão misto de disfunção sistólica e diastólica.', false),
(gen_random_uuid(), '8baddc7e-b426-40d5-8f7f-00ba834e7912', 'c', 'As arritmias cardíacas respondem pela maior parte das mortes súbitas, especialmente de homens jovens.', false),
(gen_random_uuid(), '8baddc7e-b426-40d5-8f7f-00ba834e7912', 'd', 'O ecocardiograma pode revelar aumento da espessura da parede do ventrículo esquerdo, dilatação e disfunção ventricular. Os níveis plasmáticos de ferro e ferritina e, especialmente a saturação de transferrina, estão elevados.', false),
(gen_random_uuid(), '8baddc7e-b426-40d5-8f7f-00ba834e7912', 'e', 'O tratamento envolve flebotomias repetidas (sangrias terapêuticas) e agentes quelantes, como a desferoxamina.', false),

(gen_random_uuid(), 'e279f496-5efa-4384-bd32-3f94cb36dbad', 'a', 'Biópsia cardíaca está indicada para se definir a etiologia antes de se atribuir um diagnóstico de cardiomiopatia dilatada idiopática.', true),
(gen_random_uuid(), 'e279f496-5efa-4384-bd32-3f94cb36dbad', 'b', 'Presença de padrão restritivo de disfunção diastólica é mais comumente observado em pacientes com sobrecarga de volume na insuficiência cardíaca "descompensada" e geralmente melhora com o início da terapia com diuréticos e vasodilatadores.', false),
(gen_random_uuid(), 'e279f496-5efa-4384-bd32-3f94cb36dbad', 'c', 'Um padrão de realce tardio não transmural do gadolínio com distribuição não coronária em um ventrículo esquerdo dilatado sugere cardiomiopatia dilatada.', false),
(gen_random_uuid(), 'e279f496-5efa-4384-bd32-3f94cb36dbad', 'd', 'A cardiomiopatia dilatada familiar é caracterizada pela penetrância dependente da idade, o que significa que um indivíduo portador de um alelo causador de cardiomiopatia manifestará evidências do fenótipo da cardiopatia com o aumento da idade.', false),
(gen_random_uuid(), 'e279f496-5efa-4384-bd32-3f94cb36dbad', 'e', 'O consumo excessivo de álcool é cardiotóxico e pode se manifestar como cardiomiopatia dilatada.', false),

(gen_random_uuid(), '2e5c751b-b592-4412-805e-63bd8d1b2d4c', 'a', 'A biópsia endomiocárdica não é eficaz para o diagnóstico.', true),
(gen_random_uuid(), '2e5c751b-b592-4412-805e-63bd8d1b2d4c', 'b', 'Tem início abrupto, usualmente no decorrer de duas semanas de uma doença viral.', false),
(gen_random_uuid(), '2e5c751b-b592-4412-805e-63bd8d1b2d4c', 'c', 'Aproximadamente 10% dos pacientes com miocardite demonstrada por biópsia apresentam miocardite fulminante.', false),
(gen_random_uuid(), '2e5c751b-b592-4412-805e-63bd8d1b2d4c', 'd', 'Os pacientes apresentam comprometimento hemodinâmico e hipotensão, necessitando frequentemente de vasoconstritores e suporte mecânico.', false),
(gen_random_uuid(), '2e5c751b-b592-4412-805e-63bd8d1b2d4c', 'e', 'O ecocardiograma revela hipocinesia global difusa, raramente mostra dilatação cardíaca e tipicamente demonstra espessamento da parede ventricular por edema miocárdico.', false),

(gen_random_uuid(), 'a9753463-7cd7-4de5-b183-2b4eef3a03ab', 'a', 'O diagnóstico diferencial mais importante é a cardiomiopatia dilatada.', false),
(gen_random_uuid(), 'a9753463-7cd7-4de5-b183-2b4eef3a03ab', 'b', 'O exame complementar a ser realizado preferencialmente é a ressonância magnética cardíaca com gadolínio.', false),
(gen_random_uuid(), 'a9753463-7cd7-4de5-b183-2b4eef3a03ab', 'c', 'A cardiomiopatia de Takotsubo mostra alteração da contratilidade do ventrículo esquerdo (VE), especialmente apical, embora possa ser basal, médio-ventricular ou de uma região ventricular, na ausência de coronariopatia obstrutiva.', true),
(gen_random_uuid(), 'a9753463-7cd7-4de5-b183-2b4eef3a03ab', 'd', 'A recorrência da cardiomiopatia de Takotsubo é alta.', false),
(gen_random_uuid(), 'a9753463-7cd7-4de5-b183-2b4eef3a03ab', 'e', 'Vasopressores devem ser usados rotineiramente em paciente com Takotsubo.', false);
